          duration: "2:20",
          xy: [400, 345],
          next: "出诗史堂继续向西，到柴门前停。",
          script: "进堂之前，先把脚步放慢。'诗史'这个称号不是后人追封的。晚唐人孟棨在《本事诗》里记：杜甫'当时号为诗史'，也就是说他活着时就被这样叫了。凭什么？因为他拿诗当史笔：逃难的人家、饿死的婴儿、被抓去当兵的老翁，全进了他的句子。堂正中杜甫像的神情你也看一眼：愁，但不垮。一千多年来中国人一代代回到这里，谢的就是这个替普通人记账的人。",
