      "往茶铺边站一站，先看人，再看茶。文殊院的香园把素斋和盖碗茶放在同一个院坝里，信众、游客、街坊共用一片树荫。寺院开的茶铺，这在全国都不多见。一碗素面、一杯素茶，价格平得不像景区。重点不是吃喝，是看成都怎么允许人坐下来：桌椅摆得松，服务员穿行不急，坐多久没人管。民国时成都就有'一城居民半茶客'的说法，你面前这个院坝，就是那句话还活着的证据。",
      "走到街口宽处，抬起头，把两边的屋顶扫一遍。文殊坊是围着寺院做的川西民居街区，三样东西最好认：穿斗木架、封火墙、小青瓦。别只盯着仿古立面，看街道的宽度、店铺的开口、人流在哪里拐弯——城市更新改变的是人怎么进、怎么停、怎么走。想验证这街区有没有真生活，去找宫廷糕点铺：门前常年排队，数一数队里本地口音占几成，比任何调研报告都准。寺里走中轴，坊里走回字，两种动线正好对照。",
      "站到路口安全的位置，先别过马路，数一数一分钟里从你身边经过多少人。春熙路1924年开街，名字取自《道德经》'众人熙熙，如登春台'。一百年过去，路口的人流密度没辜负这四个字。主持修路的军阀杨森大概想不到，这条街后来成了成都商业的第一地标，百年老号和最新首店挤在同一段路口。从寺院走到这里，你其实穿过了成都的三种速度：禅院的慢、街坊的匀、商圈的快。等红绿灯变两次，你再过街。",
