          script: "沿路边走边数：狮子、獬豸、骆驼、大象、麒麟、石马，六种各四只，两立两卧，一共二十四只，六百一十五米的路就是它们的仪仗序列。留意骆驼。江南的帝陵里站着沙漠的牲口，这是明初朝廷的心思：四方来朝的想象，要刻进石头里陪皇帝。石兽六百多年没挪过窝，狮子的脊背被人摸得发亮；秋天银杏叶落满底座时，本地人管这段叫最美六百米。别只顾着拍大象，最容易错过的是獬豸：那只独角神兽在古代管辨忠奸，御史的帽子就叫獬豸冠，是编进仪仗里的司法。",
