    "明孝陵1961年为首批全国重点文物保护单位，2003年7月作为明清皇家陵寝扩展项目列入《世界遗产名录》，是南京首处世界遗产。",
    "四方城内神功圣德碑立于永乐十一年（1413年），碑文为朱棣亲撰，标志着前后营建三十二年的明孝陵正式收尾。",
    "石象路两侧排列狮、獬豸、骆驼、象、麒麟、马六种石兽，每种四只共二十四只，是明初石刻仪仗的完整序列。",
