    "无梁殿建于明洪武十四年（1381年），全殿砖砌拱券不设木梁，是国内现存时代最早、规模最大的同类殿宇之一。",
    "1931年无梁殿被改建为国民革命军阵亡将士公墓祭堂，四壁一百一十块青石碑刻有三万余名阵亡将士姓名。",
