          location: "站在点春堂正门前的空地上，看门额和厅堂面阔",
          duration: "2:20",
          xy: [410, 340],
          next: "继续向园西走，穿过花墙小门，到玉玲珑前的庭院停下。",
          script: "走到点春堂门前先别进去，回头看水池对面那座雕花小戏台。它叫打唱台。这一片本是福建花糖业商人的公所，宴客听戏的地方；1853年小刀会起义占领上海县城，刘丽川他们把指挥所设进这座厅堂，一守十七个月。戏台对着指挥部，中间只隔一池水：那边原在唱曲，这边在部署守城。堂名点春，出自苏轼的词，本来极文雅；如今堂里陈列的是刀矛和义军告示。把它当成上海最不像战场的一处战场来看，比背年代有用。",
