  routeSourceNotes["yongzuo-shuangta"] = "全国重点文物保护单位名录（2006年第六批）、永祚寺维基与景区官方介绍、太原日报“国宝太原”系列报道、山西大学期刊《太原的标志——双塔寺》。";
