    "修复后的城墙全长3700米、高11米，设城楼4座、角楼4座、望楼36座，恢复了明代县城的防御轮廓。",
    "城内恢复县衙、文庙、城隍庙等公共建筑，十字街骨架保留明清县城的街巷肌理，县衙与城隍庙体现“阴阳两界”并置的治理观。",
