  const yongle = city.routes.find((r) => r.id === "yongle-murals");
  const yongleScripts = [
    "进山门之前，先在中轴线上站住，把这条线看直：山门、无极门、三清殿、纯阳殿、重阳殿，从南到北一路排上去，背后衬着中条山。但先告诉你一件颠覆直觉的事：这条中轴原本不在这儿。整座永乐宫是从二十多公里外的永乐镇搬来的。上世纪五十年代修三门峡水库，原址进了淹没区，国家把宫殿和壁画原物原貌迁到了这里。你第一眼看到的'严丝合缝'，其实是一场大搬家之后重新拼起来的。这座宫始建于1247年，前前后后盖了一百多年，几乎和元朝同始终。",
    "走到无极门前，先别迈门槛，站在门外看这座门殿本身。它又叫龙虎殿，是元代留下来的原构，梁柱之间带着元代建筑特有的粗放。再看门内：它故意挡住你一部分视线，只把后面三清殿的屋檐露出来。这道门是把外部世界和宫观隔开的开关，跨过去，中轴就开始安静了。还有个细节多数人不知道：1959年搬迁时，这座门的每根构件都被编号拆散、运到这里再按原样装回去，你手扶的这根柱子，既摸过元代工匠的斧头，也摸过搬迁队的撬棍。",
    "到了三清殿台基下，先退后几步，把屋顶、台基和殿身的比例看完整。这是永乐宫体量最大的殿，面阔七间、单檐庑殿顶，琉璃脊饰在太阳底下发亮。等会儿进殿你会看到满墙的《朝元图》，人物近三百位，密得喘不过气，所以现在先把方向感建立好：门在南，主像在北，壁画从两边墙上铺开。再记一个进去才看得明白的点：殿里的柱子比常规大殿少。为了腾出完整的墙面给壁画，工匠大胆减柱，殿内因此比外表看起来空旷得多，这是元代大木作的胆量。",
    "进了殿别横扫，先沿墙边走到一侧，从队列的头开始看。这铺《朝元图》四米多高、九十多米长，二百八十六位神祇列队朝拜，主神有三米高，身边神官也个个超过真人，衣纹全用铁线描，一根线能拉一两米不断。给你两个抓手：一是认人，八位帝王装束的主神最好找；二是找缝——当年搬迁时全宫壁画被避开眉眼切成五百五十块，装箱运来再拼回墙上，接缝至今留在墙面上。这些神在墙上站了七百年，中间还集体搬过一次家。",
    "走到最后两座殿，先把看神仙的眼睛换成看市井的眼睛。纯阳殿用五十二幅连环画画完吕洞宾从出生到得道的一生，仔细看画里的背景：酒馆、茶楼、药铺、渡口，全是元代市井的实景，可以当风俗纪录片看。殿墙上还留着画工的题记：'禽昌朱好古门人'，张遵礼、李弘宜、王士彦这些名字都在。当年是两个画工班子隔着幕布分头画，谁画得好谁接下一座殿，这套壁画其实是比出来的。重阳殿接着讲王重阳和全真七子。看完回头走，眼睛累了就去院里站一会儿。"
  ];
