const state = {
  view: "cities",
  cityId: data.cities[0].id,
  routeId: data.cities[0].routes[0].id,
  stopIndex: 0,
  introSelected: false,
  tab: "info",
  isPlaying: false,
  progress: 0,
  tick: null,
  voiceTimers: [],
  audioElement: null,
  audioAsset: null,
  audioSourceMode: "speech",
  playStartedAt: 0,
  playDurationSeconds: 0,
  pausedSeconds: 0,
  activeSegmentIndex: 0,
  playbackMode: "stop",
  playbackRate: 1,
  musicOn: true,
  musicElement: null,
  musicTrack: 0,
  routeTourMode: false,
  stopImages: null,
  routeLayouts: null,
  routeTourCompleted: false,
  downloaded: new Set(["yungang"]),
  libraryDownloaded: false,
  reviewMode: false,
  reviewChecks: new Set()
};

const app = document.querySelector("#app");
const validTabs = new Set(["info", "script"]);

function getCity() {
  return data.cities.find((city) => city.id === state.cityId) || data.cities[0];
}

function getRoute() {
  const city = getCity();
  return city.routes.find((route) => route.id === state.routeId) || city.routes[0];
}

function getStop() {
  return getRoute().stops[state.stopIndex] || getRoute().stops[0];
}

function showCities() {
  stopAudio();
  state.view = "cities";
  render();
}

function showCityRoutes() {
  stopAudio();
  state.view = "routes";
  render();
}

function setCity(cityId) {
  const city = data.cities.find((item) => item.id === cityId);
  if (!city) return;
  stopAudio();
  state.view = "routes";
  state.cityId = city.id;
  state.routeId = city.routes[0].id;
  state.stopIndex = 0;
  state.introSelected = false;
  state.tab = "info";
  loadReviewChecks();
  render();
}

function setRoute(routeId) {
  const route = getCity().routes.find((item) => item.id === routeId);
  if (!route) return;
  stopAudio();
  state.view = "route";
  state.routeId = route.id;
  state.stopIndex = 0;
  state.introSelected = false;
  state.tab = "info";
  loadReviewChecks();
  render();
}

function setStop(index) {
  const route = getRoute();
  if (index < 0 || index >= route.stops.length) return;
  stopAudio();
  state.view = "route";
  state.stopIndex = index;
  state.introSelected = false;
  render();
}

function selectIntro() {
  stopAudio();
  state.view = "route";
  state.introSelected = true;
  render();
}

function selectStopAndPlay(index) {
  const alreadyHere = state.view === "route" && !state.introSelected && state.stopIndex === index;
  if (alreadyHere && state.isPlaying) {
    scrollSheetIntoView();
    return;
  }
  setStop(index);
  scrollSheetIntoView();
  speakCurrentStop();
}

function selectIntroAndPlay() {
  if (state.isPlaying && state.playbackMode === "intro") {
    state.view = "route";
    state.introSelected = true;
    render();
    scrollSheetIntoView();
    return;
  }
  selectIntro();
  scrollSheetIntoView();
  speakRouteIntro();
}

function scrollSheetIntoView() {
  if (typeof window === "undefined") return;
  if (window.innerWidth && window.innerWidth > 1040) return;
  window.setTimeout(() => {
    document.querySelector(".stop-sheet")?.scrollIntoView?.({ behavior: "smooth", block: "start" });
  }, 0);
}

function setTab(tab) {
  if (!validTabs.has(tab)) return;
  state.tab = tab;
  render();
}

function applyInitialUrlState() {
  if (typeof URLSearchParams === "undefined") return;
  const params = new URLSearchParams(window.location?.search || "");
  state.reviewMode = params.get("review") === "1";
  const city = data.cities.find((item) => item.id === params.get("city"));
  if (city) {
    state.view = "routes";
    state.cityId = city.id;
    state.routeId = city.routes[0].id;
  }
  const route = getCity().routes.find((item) => item.id === params.get("route"));
  if (route) {
    state.view = "route";
    state.routeId = route.id;
  }
  const stop = Number(params.get("stop"));
  if (Number.isInteger(stop) && stop >= 0 && stop < getRoute().stops.length) state.stopIndex = stop;
  if (params.get("tab") === "script") state.tab = "script";
  loadReviewChecks();
}

function toggleDownload() {
  downloadRouteScriptPackage(getCity(), getRoute());
  state.downloaded.add(state.routeId);
  render();
}

function toggleLibraryDownload() {
  downloadLibraryProductionPackage();
  state.libraryDownloaded = true;
  render();
}

function safeFileName(value) {
  return String(value)
    .replace(/[\\/:*?"<>|]/g, "-")
    .replace(/\s+/g, "")
    .slice(0, 80);
}

function contentAnchorForStop(route, index) {
  return contentAnchors[route.id]?.[index] || "";
}

function sourceNoteForRoute(route) {
  return routeSourceNotes[route.id] || "";
}

function routePickerItems(city, route) {
  return [route, ...city.routes.filter((item) => item.id !== route.id)];
}

function routeEntries() {
  return data.cities.flatMap((city) => city.routes.map((route) => ({ city, route })));
}

function routeAudioAssets(route) {
  return audioAssetManifest.routes[route.id] || null;
}

function audioPlaybackAsset(route, index = state.stopIndex, mode = state.playbackMode) {
  const assets = routeAudioAssets(route);
  if (!assets) return null;
  if (mode === "intro") return assets.intro || null;
  return assets.stops?.[index] || null;
}

function audioAssetCount(route) {
  const assets = routeAudioAssets(route);
  if (!assets) return 0;
  return Number(Boolean(assets.intro)) + Object.keys(assets.stops || {}).length;
}

function audioAssetSummary() {
  return routeEntries().reduce(
    (summary, { route }) => {
      const routeAssets = audioAssetCount(route);
      if (routeAssets > 0) summary.routes += 1;
      summary.assets += routeAssets;
      return summary;
    },
    { routes: 0, assets: 0 }
  );
}

function audioPlaybackSourceLabel(route, index = state.stopIndex, mode = state.playbackMode) {
  return audioPlaybackAsset(route, index, mode) ? "真实音频样例" : "浏览器语音";
}

function mergeAudioAssetManifest(manifest) {
  if (!manifest?.routes) return;
  audioAssetManifest = {
    ...audioAssetManifest,
    ...manifest,
    routes: {
      ...audioAssetManifest.routes,
      ...manifest.routes
    }
  };
}

function loadAudioAssetManifest() {
  if (typeof fetch !== "function") return;
  fetch("audio-assets/manifest.json", { cache: "no-cache" })
    .then((response) => (response.ok ? response.json() : null))
    .then((manifest) => {
      if (!manifest) return;
      mergeAudioAssetManifest(manifest);
      render();
    })
    .catch(() => {});
  fetch("data/stop-images.json", { cache: "no-cache" })
    .then((response) => (response.ok ? response.json() : null))
    .then((images) => {
      if (!images) return;
      state.stopImages = images;
      render();
    })
    .catch(() => {});
  fetch("data/route-layout.json", { cache: "no-cache" })
    .then((response) => (response.ok ? response.json() : null))
    .then((layouts) => {
      if (!layouts) return;
      state.routeLayouts = layouts;
      render();
    })
    .catch(() => {});
}

function stopImageFor(route, index) {
  const entry = state.stopImages?.[`${route.id}/${index}`];
  if (!entry?.file) return null;
  return { src: resolveAudioSrc(entry.file), credit: entry.name || "" };
}

// Real-geography layouts (OSM) override the hand-placed canvas coordinates
// when per-stop coverage is good enough; layouts that only carry a site-level
// anchor (anchorOnly) still replace the decorative backdrop with real
// features while keeping the authored stop positions.
function layoutFor(route) {
  const layout = state.routeLayouts?.[route.id];
  if (!layout) return null;
  if (layout.stopsXy && layout.stopsXy.length === route.stops.length && (layout.confident ?? 0) >= 0.6) return layout;
  if (layout.anchorOnly && layout.features) return { ...layout, stopsXy: null };
  return null;
}

function mapStopXY(route, index) {
  const layout = layoutFor(route);
  return layout?.stopsXy?.[index] || route.stops[index].xy;
}

function mapPoints(route) {
  return route.stops.map((_, index) => mapStopXY(route, index));
}

function layoutPath(points, close) {
  if (!points || points.length < 2) return "";
  const d = points.map(([x, y], index) => `${index === 0 ? "M" : "L"}${Math.round(x)} ${Math.round(y)}`).join(" ");
  return close ? `${d}Z` : d;
}

function layoutIsClosed(points) {
  if (!points || points.length < 4) return false;
  const [x0, y0] = points[0];
  const [x1, y1] = points[points.length - 1];
  return Math.hypot(x1 - x0, y1 - y0) < 4;
}

// Render real OSM features (already projected into the 960x680 canvas space by
// scripts/fetch-geo-layout.mjs) in the same hand-drawn visual language.
function renderLayoutBackdrop(route, layout) {
  const { water = [], roads = [], rail = [], green = [] } = layout.features || {};
  const strokes = (list, className) =>
    list
      .map((points) => {
        const closed = layoutIsClosed(points);
        return `<path class="${className}${closed ? " area" : ""}" d="${layoutPath(points, closed)}"></path>`;
      })
      .join("");
  return `
    ${strokes(green, "map-park layout-green")}
    ${strokes(water, "map-water layout-water")}
    ${strokes(roads, "map-road layout-road")}
    ${strokes(rail, "map-road-soft layout-rail")}
    ${mapLabel(110, 150, `${route.theme || route.title} · ${route.start} 到 ${route.end} · 实景方位`, "map-landmark")}
  `;
}

function buildRouteIntroSegments(route, startIndex = 0) {
  const safeStartIndex = Math.max(0, Math.min(route.stops.length - 1, startIndex));
  const firstStop = route.stops[safeStartIndex];
  const finalStop = route.stops[route.stops.length - 1];
  const startLabel = safeStartIndex === 0
    ? route.start
    : `第 ${safeStartIndex + 1} 站：${firstStop.title}`;
  const scopeLabel = safeStartIndex === 0 ? "整条路线" : "剩余路线";
  const seed = narrationSeed(route, 0);
  const firstLines = [
    `这条路线是${route.title}。先确认你现在站在${startLabel}。不要急着往前走，听我把这条线的来历讲完再动身。先把手机音量调到能听清路口声音的程度，别让它盖过现场。`,
    `你现在在${startLabel}，这条路线叫${route.title}。开始之前先停一下：把手机音量调好，不用急着走，我会先告诉你这条线怎么走、每一站看什么，再正式开始。`,
    `${route.title}从这里开始：${startLabel}。开走之前，把手机音量调到能听清周围动静的程度。接下来的几分钟都交给我，我先交代路线，再带你进第一站。`
  ];
  const secondLines = [
    `接下来会听${scopeLabel}，终点是${route.end}，全线${route.distance}，建议游览${visitDurationLabel(route)}，语音覆盖约 ${Math.round(routeStopsAudioMinutes(route))} 分钟。${route.mapNote}走到哪一站，你就点哪一站，随时可以从当前这一站接着听。`,
    `这条线${route.distance}，从${route.start}走到${route.end}，建议留出${visitDurationLabel(route)}。${route.mapNote}地图上的每个编号点都能直接点开听，不用按顺序，也不用从头开始。`,
    `${scopeLabel}大约${route.distance}，终点在${route.end}。${route.mapNote}每一站的讲解里都留了给你自己看的时间，听到留白提示就把手机收起来，用眼睛看。`
  ];
  const thirdLines = [
    `路线主题是${route.theme}。正式开始前请先确认这一站：${firstStop.title}，站位是${firstStop.location}。听完每一站后，我都会告诉你下一步怎么走，最后会在${finalStop.title}收束。想跳过开场，随时可以点「直接进入第 1 站」。`,
    `这条线讲的是${route.theme}。第一站是${firstStop.title}，${firstStop.location}。每一站听完我会告诉你怎么走，到${finalStop.title}结束。如果已经在第一站旁边，可以直接点地图上的 1 号点开始。`,
    `${route.theme}——这条线的主题。先走到${firstStop.title}：${firstStop.location}。后面每一站听完都有下一步的走法，最后收在${finalStop.title}。不想听开场的话，点「直接进入第 1 站」就行。`
  ];
  const sources = [
    {
      label: "开场站位",
      text: firstLines[seed % firstLines.length]
    },
    {
      label: "路线看法",
      text: secondLines[(seed + 1) % secondLines.length]
    },
    {
      label: "第一步",
      text: thirdLines[(seed + 2) % thirdLines.length]
    }
  ];
  const segments = [];
  let cursor = 0;
  sources.forEach((source) => {
    segments.push({ minute: cursor, ...source });
    cursor += estimateSpeechSeconds(source.text) / 60 + 0.02;
  });
  return segments;
}

function routeIntroDurationMinutes(route, startIndex = 0) {
  const segments = buildRouteIntroSegments(route, startIndex);
  const last = segments[segments.length - 1];
  return last.minute + estimateSpeechSeconds(last.text) / 60 + 0.1;
}

function routeIntroDurationLabel(route, startIndex = 0) {
  return `约 ${Math.max(1, Math.ceil(routeIntroDurationMinutes(route, startIndex)))} 分钟`;
}

const cityIntros = {
  datong: "先说说大同这座城。公元三九八年，鲜卑人拓跋珪把都城从盛乐迁到这里，起名平城。一个从草原走出来的王朝，在农牧交界的这块台地上安顿下来，一边学汉人的礼制建宫殿、立太学，一边把自己的信仰凿进山崖。城西十六公里的武周山南麓，沙门统昙曜领着工匠开出五个大窟，据说把北魏五位皇帝的面容刻进了佛身——云冈石窟的第一锤就这么落下去了。平城时代的宫里还有一位关键人物，文明太后冯氏，她临朝称制十几年，均田制、三长制都是她手里推出来的，孙子孝文帝接着把汉化做到底，改姓氏、穿汉服，然后迁都洛阳，把开窟的手艺也一并带去了龙门。再往后五百年，辽和金先后把这里设为西京，一设就是两百年。华严寺薄伽教藏殿里那尊合掌露齿菩萨，露着牙笑了一千年，郑振铎干脆叫它东方维纳斯；善化寺的大殿压得很低、开得很阔，是辽金建筑特有的气度。到了明代，大将军徐达在旧城外包上城砖，大同成了九边重镇里最硬的一块，代王府门前那块九龙壁，比北京北海的那块早三百多年，还要大上一圈。近代这座城靠煤养活了几代人，煤灰落尽，城墙重新合拢，城里辽金的殿、明代的壁，和城外崖壁上的佛，把一千五百年摊在你眼前。云冈中期的洞窟里常见两佛并坐的题材，那是冯太后和孝文帝祖孙共同执政的年代刻进石头的影子；晚期的洞窟越凿越小，佛像的笑容却越来越温和，一个王朝的力气和心气，都写在崖壁上。我们从石窟开始，再走回城里。",
  jinzhong: "先说说晋中。明清几百年，中国的钱有一大半是从这片盆地里流进流出的。道光初年，平遥西裕成颜料庄的掌柜雷履泰把分号之间的汇兑生意独立出来，挂出日升昌的牌子，中国第一家票号就这么开张了。之后几十年，平遥、祁县、太谷的票号开遍全国，分号最远到了莫斯科和加尔各答，北京的军饷、江南的货款，全靠几张纸在各省之间飞来飞去。密押用诗句当密码，「谨防假票冒取，勿忘细视书章」十二个字代表十二个月，这套防伪办法比同期的西方银行不差。钱多了，房子就往讲究里盖：乔家大院的砖雕、王家大院一重一重的院落，是晋商把生意规矩和家教一起刻进砖木的结果，门楣上刻的都是「俭养德」「慎言语」这类话。再往前看，平遥城外双林寺的两千多尊彩塑里，那尊韦驮像被行家叫作东方大卫；镇国寺的万佛殿是五代北汉留下来的木构，一千多年没大修过，斗拱比柱子还抢戏。晋商败落得也快，辛亥之后票号成批倒闭，只留下这些院子和城墙。晋中的好看，在于它把会打算盘和会过日子放在了一起。晋商的商路最远走到恰克图，驼队出张家口，把福建的茶叶换回来俄国的皮毛和银两；平遥的城墙是明洪武年间扩建的，六道城门摆成龟城的格局，到今天还完完整整，城墙上的敌楼和垛口一个不缺。我们从城墙和票号走起。",
  taiyuan: "先说说太原。两千五百年前，赵简子的家臣董安于在晋水边上筑起晋阳城，几年之后智伯引水灌城，晋阳城泡在水里一年多也没塌，三家分晋的大戏就在这段城墙上演完，战国的格局从此定下。这座城后来做过九个王朝的都城或陪都，李渊父子从晋阳起兵打出大唐，武则天是并州文水人，所以太原也叫龙城。可惜公元九七九年，宋太宗打下北汉之后又怕这座城再出天子，先烧后灌，把一千五百年的晋阳城夷为平地，如今的太原城是潘美在唐明镇上另起炉灶建起来的。城西南的晋祠还守着源头：那是给周成王弟弟唐叔虞的祠庙，三千年的周柏歪在殿前，北宋的圣母殿用八条木雕盘龙绕柱，殿前的鱼沼飞梁是一座十字形的古桥，梁思成说这样的孤例他只在画上见过。再往山上走，天龙山的石窟在二十年代被盗凿得遍体鳞伤，佛头散落各国；城东南永祚寺的双塔看了四百年，是太原人认路的老地标。山西博物院里，晋侯鸟尊和虞弘石椁把晋国的来路摆得清清楚楚。这座城不喧哗，但每一步都踩着年头。城西的蒙山大佛开凿于北齐，比乐山大佛早一百多年，元末之后佛头失踪，大佛的身子被荒草埋了六百年，前些年才重新接上佛头对外开放。晋祠里的难老泉长年十七度，李白写过「晋祠流水如碧玉」；泉边的侍女像四十三尊，一尊一个神情，站着看久了能分出谁的心事重。我们从晋祠开始听。",
  xinzhou: "先说说忻州。山西的脊梁在这里拐了个弯，五台山在北，雁门关在南，忻州就卡在这条走廊的正中间，自古是晋北的锁钥。五台山的香火从东汉烧到今天，传说汉明帝年间就有了大孚灵鹫寺，显通寺的铜殿用了十万斤铜，菩萨顶的琉璃瓦是清代皇家寺院的规格，康熙、乾隆上山都住在这里，青庙和黄庙共住一山，汉传佛教和藏传佛教就这么挨着过了一千多年。城外豆村的山坳里藏着两件国宝：佛光寺东大殿建于唐大中十一年，梁上有宁公遇的墨书题记；南禅寺大殿比它还要早七十五年，是中国现存最早的木构建筑。一九三七年六月，梁思成和林徽因骑着毛驴找到佛光寺，拿梁架题记对上经幢，终于把「中国没有唐代木构」的日本断言推翻——几天后卢沟桥枪响，他们揣着图纸开始逃难。往南走，雁门关的城墙盘在山脊上，李牧在这里驻守过，昭君从这里出塞，杨业在旁边的陈家谷兵败被俘，一九三七年八路军又在这条沟里伏击日军。一座山、一道关，两千年的仗都在这儿打。五台山的夏天比山下凉十几度，七月进山也要带外套，所以历代皇帝叫它清凉山，顺治出家的传说就一直挂在这座山上；黛螺顶下一千零八十级台阶，朝台的人一步一叩首，到今天台阶上还是一排排磕长头的身影。我们从台怀镇走起。",
  shuozhou: "先说说朔州。战国时这里叫马邑，传说蒙恬北逐匈奴时在这里筑城，城名一直用到今天。公元前二〇〇年，汉高祖被匈奴围在附近的白登山七天七夜，靠陈平的计策才脱身；公元前一三三年，汉武帝在这里设下马邑之谋，三十万汉军埋伏在山谷里想一口吃掉匈奴主力，虽然走漏了风声，汉匈之间百年的战和大幕却就此拉开。两千年里，这里是中原和草原反复易手的边地，留下的东西却惊人地完整：崇福寺的弥陀殿是金代原构，殿顶的琉璃脊饰、殿内的壁画和门窗棂花，被行家合称金代五绝；应县的佛宫寺释迦塔，也就是应县木塔，建于辽清宁二年，六十七米高，全身没有一颗铁钉，全靠斗拱一层层摞起来，快一千年里扛过七次大地震，军阀混战时挨过两百多发炮弹，至今没倒，梁思成一九三三年爬上去测绘，下来之后说「不见此塔，不知木构的可能性到了什么程度」。再往西走到杀虎口，明清几百年，无数山西人从这里出关走西口讨生活，桥下的青石板被驼队和脚步磨得发亮。朔州不大，但每段墙都见过大场面。木塔的明层之间藏着暗层，暗层里是一圈圈斜撑，现代工程师说那是九百年前的桁架结构；塔内的辽代彩塑一层一个格局，底层的大佛高十一米，在莲花座上坐了快一千年。二〇一六年，它被吉尼斯认证为世界最高的木塔，但这个头衔对它来说其实最不重要。我们从佛宫寺的木塔开始。",
  yuncheng: "先说说运城。黄河在这里拐完最后一个弯，冲积出山西最富庶的盆地。传说里舜都蒲坂、禹都安邑都在这一带，所以运城人管自己的家乡叫最早的中国；城南的中条山下躺着中国最早开发的盐池，春秋时猗顿在这里贩盐致富，富到和陶朱公齐名，唐代的盐税一度占到全国财政的八分之一。解州的关帝庙是天下武庙之祖，关羽的老家就在城南十公里，庙里的春秋楼用悬梁吊柱撑起二层回廊，站在楼下往上看，整座楼像悬空挂着，是北方古建里的孤例。永济的普救寺住着《西厢记》，张生和崔莺莺的故事从元稹的《莺莺传》写到王实甫的杂剧，寺里的莺莺塔还是明代重修的，在塔前击石能听见蛙鸣一样的回声。蒲津渡出土的开元铁牛，每尊重达几十吨，当年八尊铁牛拽着横跨黄河的浮桥，那是大唐的国家级工程。鹳雀楼虽然是新盖的，但王之涣「更上一层楼」站的位置没有变。芮城的永乐宫，上千平方米的元代壁画是道教美术的顶峰，五十年代为了躲三门峡水库，几千块壁画被一块块揭下来，整座宫殿整体搬了家。这座城是华夏文明的老家底。运城乡间还存着好几座元代的戏台，蒲剧的梆子腔从蒲州一路唱进西安；万荣的后土祠是汉武帝祭后土的地方，他在这里写下《秋风辞》，「秋风起兮白云飞」说的就是汾河入黄的那一片水。关羽在宋代被一路加封，到清代成了和孔子并列的武圣，解州关帝庙的规格也就一路涨到了宫殿级。我们从壁画中轴线走起。",
  beijing: "先说说北京。一二六七年，忽必烈让刘秉忠在金中都东北另建新城，元大都的棋盘街巷和中轴线就此定下；明朝永乐皇帝迁都过来，一四二〇年紫禁城落成，这条七点八公里的中轴线一躺就是七百五十年，前门、故宫、景山、钟鼓楼被一根看不见的尺子量着生长，二〇二四年它成了世界遗产。明清两朝二十四位皇帝在紫禁城里处理同一件事：怎么守住这么大的国家。太和殿的广场大得让每个人都不敢大声说话，三大殿在几百年里烧了建、建了烧，如今的太和殿是康熙年间重建的。出了宫城，生活就松弛下来：什刹海在元代是漕船的终点，南方的粮船一路摇进积水潭，如今水边的胡同还留着元大都的骨架，烟袋斜街的铺子后面就是人家的柴米油盐。再远一点，天坛和紫禁城同龄，回音壁能把一句悄悄话送出去几十米；颐和园的前身清漪园是乾隆给母亲修的寿礼，一八六〇年被英法联军烧掉，二十多年后慈禧挪了海军经费重建；雍和宫原是雍正的潜邸，乾隆在这里出生，后来改成喇嘛庙，汉藏蒙三种佛教拢在一进院子里。北京的好，在于皇城的尺度和胡同的日子只隔一堵墙。登上景山的万春亭往南看，紫禁城几千间房子沿一条线铺开，金色的屋脊一层压一层，那是世界上最完整的一张皇城俯视图；往北看，钟鼓楼的灰瓦接住暮色，暮鼓声到一九二四年才停下来。我们沿中轴往南往北走。",
  shanghai: "先说说上海。别看它今天是这个体量，一百八十年前还只是黄浦江边一座县城：元代一二九二年设上海县，明代嘉靖年间为了挡倭寇才筑起城墙，圈里是豫园和城隍庙，园主人潘允端为父亲潘恩修了这座园子，日子过得和江南别的县城没什么不同。一八四三年开埠之后，故事陡然加速：外滩用不到百年立起一排银行和大楼，汇丰银行大楼被当时的英国人叫作从苏伊士运河到远东白令海峡之间最讲究的建筑，沙逊大厦的绿色铜皮尖顶到今天还是天际线的主角。石库门里弄把江南民居和西方联排拼在一起，天井、客堂间、亭子间，养出独一份的市民生活——中共一大就在一幢石库门里召开，鲁迅在山阴路住了九年，张爱玲从常德公寓的窗口看电车。武康路上的梧桐树下是上世纪三十年代的公寓，武康大楼那艘船一样的造型出自匈牙利建筑师邬达克；苏州河北岸的四行仓库，墙里还留着一九三七年八百壮士死守的弹孔。这座城的迷人之处，就在于每一层时间都没被拆掉，过一条街就换一个年代。外滩的钟声来自一九二七年的海关大楼，报时曲用的是威斯敏斯特的旋律；江对岸的陆家嘴，一九九〇年浦东开发之前还是一片仓库和滩涂，三十年就长成了今天的高度。这座城的加速度，隔一条江就能看见。我们从外滩开始听。",
  xian: "先说说西安。长安这个名字，中国人记了两千年。西周在城西南建丰镐二京，秦在渭河北岸修咸阳，汉长安城的城墙一周二十五公里；到了隋唐，宇文恺规划设计的大兴城、也就是唐长安城，面积八十四平方公里，人口过百万，朱雀大街宽一百五十米，朱雀门里进出过整个盛唐的使节、商旅和留学生。玄奘从印度取经受戒归来，在慈恩寺主持修了大雁塔存经；荐福寺的小雁塔在一千三百年里历经七十多次地震，塔身裂开又合拢，当地人叫三离三合，塔顶两层的残缺比完整更有记性。今天的城墙是明代洪武年间在唐皇城基础上包砖扩建的，绕一圈十三点七公里，不少城砖上还留着当年督造府县的戳记。碑林里四千多方石头是中国的另一部纸面历史：唐玄宗亲注的石台孝经、六十多万字的开成石经，颜真卿、柳公权的字都在原碑上。回坊的烟火气是丝路留给这座城的味觉，化觉巷清真大寺把礼拜殿盖成了中国宫殿的样子。西安的用法不是凭吊，是每天仍在发生的日常——城墙根下照样有人晨练、吼秦腔。汉长安城的遗址在城西北，未央宫的夯土台高出地面十几米，张骞就是从那个方向出发去的西域；玄奘回长安后在慈恩寺开译经场，十九年译出一千三百多卷佛经，大雁塔就是为存这些经卷和佛像盖的。我们从南门上城墙听起。",
  chengdu: "先说说成都。这座城的名字三千年没变过，「一年成聚、二年成邑、三年成都」。公元前二五六年上下，蜀郡守李冰在岷江上修都江堰，鱼嘴分水、飞沙堰泄洪、宝瓶口引水，从此水旱从人，天府之国四个字有了着落，这套工程到今天还在灌溉成都平原。汉代这里织蜀锦，设锦官管理，所以成都也叫锦官城。三国时刘备在这里称帝，死后葬在惠陵，旁边的武侯祠把君臣合祀一庙，全国独一份，老百姓偏偏就认孔明，叫了几百年武侯祠，把昭烈庙的本名叫没了。杜甫为避安史之乱入蜀，在浣花溪边盖了间茅屋，四年写下两百四十多首诗，「窗含西岭千秋雪」写的就是在自己门口能望见的雪山；晚唐的薛涛在望江楼边制笺写诗，一种桃红色的小诗笺风行长安。二〇〇一年出土的金沙遗址，太阳神鸟金箔薄到零点零二厘米，把这座城的历史再往前推了三千年，直接成了中国文化遗产的标志。成都的性子藏在人民公园的盖碗茶和鹤鸣茶社的竹椅里——在这儿，慢不是缺点，是千年修来的本事。成都自古少战乱，天下一乱它反而成了收留所，唐玄宗、唐僖宗都往这里跑，所以成都的从容是有底气练出来的。这座城两千三百年没迁过址、没改过名，全世界也数不出几个。我们从公园往锦里慢慢走。",
  hangzhou: "先说说杭州。五千年前，城西北的良渚人筑起当时世界上最大的水利系统，宫殿、水坝和玉器把中华五千年从传说变成了世界遗产。公元九〇七年钱镠建吴越国，定都杭州，修海塘、疏西湖，保俶塔和雷峰塔都是那个时代的身影，吴越国三代五王保境安民，让这座城避开了五代十国的兵祸。白居易和苏轼两任太守前后脚来修湖蓄水，白堤的名字是后人对白居易的纪念，苏堤则真是苏轼拿疏浚的葑泥堆出来的，苏堤春晓、断桥残雪这些名字，是文人写给一座湖的情书，一写一千年。南宋把行在安在凤凰山下，临安城一百五十年，「暖风熏得游人醉，直把杭州作汴州」，偏安的日子过出了极致的精致。灵隐寺从东晋咸和元年开到今天，飞来峰上的三百多尊造像从五代刻到元；胡庆余堂的药香从胡雪岩手里的一八七四年飘到现在，「戒欺」两个字还挂在堂里；拱宸桥下的漕船曾把江南的米一路摇到北京，桥的名字本身就是迎接帝王的意思。西湖原本是和钱塘江相通的浅海湾，泥沙淤塞才慢慢隔出这个湖，历代治湖就是和淤塞赛跑，白居易、苏轼、明代的杨孟瑛，一任一任地清淤堆堤，没有他们，西湖早就变回沼泽了。所以西湖不是风景，是一千多年没停工的工程。我们从西湖北线走起。",
  suzhou: "先说说苏州。公元前五一四年，伍子胥奉吴王阖闾之命筑城，相土尝水、象天法地，城址两千五百年没挪过地方，盘门的水陆城门至今还立着，城门洞里一半走船一半走马。吴王的墓就在虎丘，传说下葬时有三千把剑陪葬，剑池的水绿得发暗；山上的云岩寺塔建于北宋初年，塔身斜了两米多，斜了一千年也没倒，比比萨斜塔还早两百多年。唐天宝年间，张继夜泊枫桥，一首二十八字的诗让寒山寺的钟声响了一千两百年，后来欧阳修抬杠说三更不是打钟的时候，宋朝人还真去考证出姑苏一带确实半夜打钟。宋代平江图碑上刻的河道街巷，和今天平江路一带的水巷走向还能对上。唐以后这里是江南最富的府城，拙政园是明代王献臣官场失意后修的，文徵明亲手参与设计还画了三十一景；留园的冠云峰是太湖石的极品，沧浪亭最老，北宋苏舜钦被贬后用四万钱买下废园，一句「沧浪之水清兮」用到现在。苏州的精致不是摆出来的，是两千年慢慢养出来的，连一碗头汤面都有固定时辰。明清的苏州织造署给皇宫供丝绸，全城织机上万张，日出万绸、衣被天下；阊门一带曾是全国最繁华的街市，徐扬的《姑苏繁华图》画得密密麻麻，曹雪芹的祖父曹寅就在织造署这一系统里当差。我们从拙政园往平江路走。",
  nanjing: "先说说南京。公元二二九年孙权在这里建都，起名建业，此后东晋和宋齐梁陈接力，六朝金粉四个字就粘在了这座城上。王导、谢安两大家族住的乌衣巷就在秦淮河边，刘禹锡那句「乌衣巷口夕阳斜」让这里的燕子飞了一千多年。南朝四百八十寺，鸡鸣寺的前身同泰寺是梁武帝四次舍身入寺的地方。一三六八年朱元璋在此称帝，修起当时世界上最长的城墙，现存二十五公里，城砖上刻着从府县官员到窑匠的名字，哪块砖出问题就找哪个人；明孝陵的神道在紫金山南麓躺了六百年，石像生六种石兽各两对，秋天银杏一落就是南京最美的六百米。近代的层积更厚：太平天国把天王府建在两江总督衙署里，一九一二年孙中山在同一个院子里就任临时大总统，后来它成了总统府；颐和路一带的梧桐和民国小楼，把二十世纪上半叶的风云装进几条安静的街道。秦淮河的灯影从南朝晃到今天，桨声里一半是李香君的媚香楼，一半是朱自清和俞平伯同题写过的那篇散文。南京城墙的砖来自五个省一百多个州县，砖窑沿长江排开，烧好船运进城，算是中国最早的标准化建材；解放门那一段城墙上，玄武湖、鸡鸣寺的药师佛塔和紫峰大厦挤在同一个画面里，六百年和二十年只隔一条湖。我们从台城往总统府走。",
  guilin: "先说说桂林。公元前二一四年，秦始皇派史禄开凿灵渠，一条三十多公里的水道用铧嘴把湘江水分成三七开，接通了长江和珠江两大水系，中原的船第一次能摇进岭南，秦军得以平定百越，桂林从此成了中原进入广西的门户。宋代王正功在独秀峰下刻了一句「桂林山水甲天下」，这块石刻湮没了几百年，一九八三年才被重新发现，一句话替这座城做了八百年的广告。明代朱元璋把侄孙朱守谦封到这里做靖江王，王城的中轴是标准藩王府格局，十四代王爷住了两百八十年，末代靖江王的儿子朱若极国破后出家，成了画僧石涛。象鼻山是这座城递给世界的名片，水月洞里的倒影被宋人写进诗里；顺漓江下去八十三公里到阳朔，兴坪附近的黄布倒影印在二十元人民币的背面，西街的青石板被几百年的脚步磨亮。在桂林，山水不是背景，是城市的一部分，山就在街口，水就在窗下。桂林的峰林是两亿多年前海底的石灰岩，被雨水一条条溶出来的，徐霞客在崇祯十年来到这里，一游一个多月，说这里的山如青莲出水；抗战时期桂林成了大后方的文化城，书店、报社、剧团挤满漓江边，欧阳予倩就在这里改桂剧、办戏校。我们从象鼻山往王城走。",
  chongqing: "先说说重庆。嘉陵江和长江在这里交汇，战国时这里是巴国的地界，秦灭巴后设巴郡筑江州城，这座城从开局就长在江和山的褶皱里，出门是坡，回家也是坡。一一八九年，宋光宗先封恭王再当皇帝，自诩双重喜庆，重庆这个名字用到了今天。南宋末年，合川钓鱼城在嘉陵江边的山头上挡了蒙古大军三十六年，一二五九年蒙哥汗倒在城下，欧亚大陆的战局因此拐弯，西方人后来叫它上帝折鞭处。明清的湖广填四川延续上百年，数百万移民沿江而上，东水门边的湖广会馆把他们的戏台和乡愁留到了今天。一八九一年重庆开埠，抗战八年它是陪都，扛过了六年半的大轰炸，防空洞挖满了整座山。十八梯和洪崖洞是把生活架在坡度上的本事，房子挂在崖壁上照样亮灯；往西一百多公里，大足宝顶山的石刻是南宋赵智凤领着工匠刻了七十年，牧牛图、养鸡女，崖壁上全是世俗日子。这座城的江湖气，是两千年的江水和山路养出来的。抗战时故宫的一万多箱文物曾藏在重庆的仓库和祠堂里，货船在三峡的急流里翻了又捞，最后一件没少，那是一场很少人提起的文化长征；这座城的防空洞如今变成火锅馆和加油站，洞子里的热气从战时一直冒到今天。我们从山城步道往下走。",
  guangzhou: "先说说广州。公元前二一四年，秦将任嚣在这里筑番禺城；秦亡之后赵佗自立南越武王，南越国传了五代九十三年，第二代南越王赵眜的墓就埋在越秀山下，一九八三年挖出来，一件丝缕玉衣用两千多片玉缀成，「文帝行玺」金印比拇指大不了多少，到今天还在展厅里躺着。作为海上丝路的起点，这座城的港口开了两千年没关过门：唐代的外商聚居区蕃坊就在光塔路一带，怀圣寺的光塔给番商当过航标；光孝寺比广州城还老，六祖慧能在这里剃度，一句「仁者心动」的公案就发生在这座院子里；六榕寺的花塔是苏轼路过时题的字。清代一口通商，十三行的商人把茶叶瓷器卖到全世界，伍秉鉴一度是那个年代的世界首富。近代的沙面是珠江冲积洲上的租界，欧陆小楼一栋挨着一栋；爱群大厦一九三七年落成时夺走了广州第一高楼的头衔，粤海关的大钟楼给珠江报了一百年的时。西关的骑楼和趟栊门把市井日子过得有板有眼，早茶的一盅两件从光绪年喝到今天。食在广州，食的是两千年的开放。广州人除夕行花街的习俗从明代就有了，五代同堂、桃花、年橘，各有各的口彩；南海神庙的波罗诞办了一千多年，祭的是海神洪圣王，庙里的碑刻着历代皇帝遣官祭海的公文——一座庙就是一部海上贸易史。我们从西关往沙面走。"
};

const reviewCheckpoints = [
  {
    label: "山西主线验收",
    title: "云冈石窟大线",
    cityId: "datong",
    routeId: "yungang",
    stopIndex: 2,
    tab: "script",
    focus: "第3站 · 第9-13窟群，检查60分钟内容、驻足留白和下一站引导"
  },
  {
    label: "Top10样例验收",
    title: "广州越秀山到纪念堂线",
    cityId: "guangzhou",
    routeId: "guangzhou-yuexiu",
    stopIndex: 4,
    tab: "script",
    focus: "终点侧看点，检查城市、景点、点位和路线完成状态"
  }
];

const reviewChecklistItems = [
  ["city-route", "城市景点", "城市先选，当前景点卡排第一"],
  ["map-stop", "点位点击", "地图编号能切到同一讲解点"],
  ["script", "文字稿", "站位、朝向、现场锚点都可读"],
  ["audio", "开场整线", "路线开场和整线按钮都清楚"],
  ["dwell", "驻足留白", "有浏览和拍照空档"],
  ["next-step", "下一站", "听完知道往哪里走，终点有完成状态"],
  ["duration", "时长覆盖", "语音覆盖不短于建议游览"],
  ["hand-map", "手绘地图", "能看出场地和行走方向"]
].map(([id, label, detail]) => ({ id, label, detail }));

function routeQualitySummary(route) {
  const visit = visitMinutes(route);
  const audio = audioMinutes(route);
  const stopCount = route.stops.length;
  const anchorCount = route.stops.filter((_, index) => contentAnchorForStop(route, index).length >= 24).length;
  const dwellCount = route.stops.reduce(
    (sum, stop, index) => sum + pauseSegmentsForStop(route, stop, index).length,
    0
  );
  const introCount = buildRouteIntroSegments(route).length;
  const mapReady =
    mobileMapContext(route) !== `${route.start} · ${route.end}` &&
    !mapBackdrop(route.id).includes("map-terrace");

  return [
    {
      label: "时长覆盖",
      value: `${audio}/${visit} 分钟`,
      detail: audio >= visit * 0.5 ? "语音达到建议游览一半以上" : "需要补长语音",
      ok: audio >= visit * 0.5
    },
    {
      label: "驻足留白",
      value: `${dwellCount} 段`,
      detail: `平均每站 ${Math.round(dwellCount / stopCount)} 段`,
      ok: dwellCount >= stopCount * 2
    },
    {
      label: "锚点覆盖",
      value: `${anchorCount}/${stopCount}`,
      detail: "点位现场锚点",
      ok: anchorCount === stopCount
    },
    {
      label: "路线开场",
      value: routeIntroDurationLabel(route),
      detail: `${introCount} 段开场`,
      ok: introCount === 3
    },
    {
      label: "手绘地图",
      value: mapReady ? "专属" : "待补",
      detail: "桌面和手机语境",
      ok: mapReady
    },
    {
      label: "点位链路",
      value: `${stopCount} 点`,
      detail: "含下一站指令",
      ok: route.stops.every((stop) => Boolean(stop.next))
    }
  ];
}

function reviewCheckpointUrl(item) {
  const params = new URLSearchParams({
    city: item.cityId,
    route: item.routeId,
    stop: String(item.stopIndex),
    tab: item.tab,
    review: "1"
  });
  return `?${params.toString()}`;
}

function reviewStorage() {
  try {
    return window.localStorage || null;
  } catch {
    return null;
  }
}

function reviewStorageKey() {
  return `cn-audio-walks-review:${state.cityId}:${state.routeId}`;
}

function loadReviewChecks() {
  const storage = reviewStorage();
  if (!storage) {
    state.reviewChecks = new Set();
    return;
  }
  try {
    const value = JSON.parse(storage.getItem(reviewStorageKey()) || "[]");
    state.reviewChecks = new Set(Array.isArray(value) ? value : []);
  } catch {
    state.reviewChecks = new Set();
  }
}

function saveReviewChecks() {
  const storage = reviewStorage();
  if (!storage) return;
  storage.setItem(reviewStorageKey(), JSON.stringify([...state.reviewChecks]));
}

function toggleReviewCheck(id) {
  if (!reviewChecklistItems.some((item) => item.id === id)) return;
  if (state.reviewChecks.has(id)) state.reviewChecks.delete(id);
  else state.reviewChecks.add(id);
  saveReviewChecks();
  render();
}

function buildRouteScriptPackage(city, route) {
  const sourceNote = sourceNoteForRoute(route);
  const lines = [
    `${city.name} · ${route.title}`,
    `主题：${route.theme}`,
    `建议游览：${visitDurationLabel(route)}`,
    `语音覆盖：${audioDurationLabel(route)}`,
    `路线：${route.start} → ${route.end}`,
    `说明：${route.mapNote}`,
    sourceNote ? `资料锚点：${sourceNote}` : "",
    ""
  ].filter((line, index, arr) => line || index === arr.length - 1);

  lines.push("路线开场");
  lines.push(`开场语音：${routeIntroDurationLabel(route)}`);
  buildRouteIntroSegments(route).forEach((segment) => {
    lines.push(`${formatMinuteMark(segment.minute)} ${segment.label}`);
    lines.push(segment.text);
  });
  lines.push("");

  route.stops.forEach((stop, index) => {
    const anchor = contentAnchorForStop(route, index);
    lines.push(`第 ${index + 1} 站：${stop.title}`);
    lines.push(`站位：${stop.location}`);
    lines.push(`朝向：${stop.cue}`);
    if (anchor) lines.push(`现场锚点：${anchor}`);
    lines.push(`本点语音：${stopAudioDurationLabel(route, index)}`);
    buildStopAudioSegments(route, stop, index).forEach((segment) => {
      lines.push(`${formatMinuteMark(segment.minute)} ${segment.label}${segment.isPause ? " [留白]" : ""}`);
      lines.push(segment.text);
    });
    lines.push(`下一步：${stop.next}`);
    lines.push("");
  });

  return lines.join("\n");
}

function buildAudioProductionManifest() {
  const routes = routeEntries();
  const routeRecords = routes.map(({ city, route }) => {
    const quality = routeQualitySummary(route);
    const stops = route.stops.map((stop, index) => {
      const segments = buildStopAudioSegments(route, stop, index);
      return {
        stopNumber: index + 1,
        title: stop.title,
        location: stop.location,
        cue: stop.cue,
        audioMinutes: stopAudioMinutes(route, index),
        segmentCount: segments.length,
        dwellPauseCount: segments.filter((segment) => segment.isPause).length,
        hasAudioAsset: Boolean(audioPlaybackAsset(route, index, "stop")),
        anchor: contentAnchorForStop(route, index),
        next: stop.next
      };
    });

    return {
      cityId: city.id,
      cityName: city.name,
      routeId: route.id,
      routeTitle: route.title,
      theme: route.theme,
      start: route.start,
      end: route.end,
      distance: route.distance,
      suggestedVisitMinutes: visitMinutes(route),
      plannedAudioMinutes: audioMinutes(route),
      routeIntroMinutes: routeIntroDurationMinutes(route),
      hasRouteIntroAudioAsset: Boolean(audioPlaybackAsset(route, 0, "intro")),
      realAudioAssetCount: audioAssetCount(route),
      stopCount: route.stops.length,
      sourceNote: sourceNoteForRoute(route),
      readyForAudioDraft: quality.every((item) => item.ok),
      quality,
      stops
    };
  });

  return {
    title: "山河听路音频制作清单",
    publicPreviewUrl: "https://cn-audio-walks.chinaaudioguide.workers.dev/",
    cityCount: data.cities.length,
    routeCount: routeRecords.length,
    stopCount: routeRecords.reduce((sum, route) => sum + route.stopCount, 0),
    plannedAudioMinutes: routeRecords.reduce((sum, route) => sum + route.plannedAudioMinutes, 0),
    routeIntroMinutes: routeRecords.reduce((sum, route) => sum + route.routeIntroMinutes, 0),
    realAudioAssetCount: routeRecords.reduce((sum, route) => sum + route.realAudioAssetCount, 0),
    realAudioRouteCount: routeRecords.filter((route) => route.realAudioAssetCount > 0).length,
    routes: routeRecords
  };
}

function buildLibraryProductionPackage() {
  const manifest = buildAudioProductionManifest();
  const lines = [
    manifest.title,
    `公开预览：${manifest.publicPreviewUrl}`,
    `城市：${manifest.cityCount}`,
    `路线：${manifest.routeCount}`,
    `点位：${manifest.stopCount}`,
    `计划点位语音：${manifest.plannedAudioMinutes} 分钟`,
    `路线开场语音：${manifest.routeIntroMinutes} 分钟`,
    `真实音频样例：${manifest.realAudioAssetCount} 个资产 / ${manifest.realAudioRouteCount} 条路线`,
    "",
    "音频制作清单"
  ];

  manifest.routes.forEach((route) => {
    lines.push("");
    lines.push(`${route.cityName} · ${route.routeTitle}`);
    lines.push(`状态：${route.readyForAudioDraft ? "可进入音频初稿" : "需补内容"}`);
    lines.push(`建议游览：${route.suggestedVisitMinutes} 分钟`);
    lines.push(`计划点位语音：${route.plannedAudioMinutes} 分钟`);
    lines.push(`路线开场：${route.routeIntroMinutes} 分钟`);
    lines.push(`真实音频样例：${route.realAudioAssetCount} 个`);
    lines.push(`点位：${route.stopCount}`);
    lines.push(`路线：${route.start} → ${route.end}`);
    if (route.sourceNote) lines.push(`资料锚点：${route.sourceNote}`);
    route.quality.forEach((item) => {
      lines.push(`- ${item.label}：${item.value}，${item.detail}`);
    });
    route.stops.forEach((stop) => {
      lines.push(`  ${stop.stopNumber}. ${stop.title}：${stop.audioMinutes} 分钟，${stop.segmentCount} 段，${stop.dwellPauseCount} 段留白，${stop.hasAudioAsset ? "已有真实音频样例" : "待生成真实音频"}，下一步：${stop.next}`);
    });
  });

  lines.push("");
  lines.push("完整路线脚本");
  routeEntries().forEach(({ city, route }) => {
    lines.push("");
    lines.push("=".repeat(48));
    lines.push(buildRouteScriptPackage(city, route));
  });

  return lines.join("\n");
}

function downloadRouteScriptPackage(city, route) {
  if (!("Blob" in window) || !("URL" in window)) return;
  const blob = new Blob([buildRouteScriptPackage(city, route)], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `${safeFileName(city.name)}-${safeFileName(route.title)}-audio-script.txt`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function downloadLibraryProductionPackage() {
  if (!("Blob" in window) || !("URL" in window)) return;
  const blob = new Blob([buildLibraryProductionPackage()], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "山河听路-全库音频制作包-20260824-v01.txt";
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function downloadAudioProductionManifest() {
  if (!("Blob" in window) || !("URL" in window)) return;
  const blob = new Blob([JSON.stringify(buildAudioProductionManifest(), null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "山河听路-音频制作清单-20260824-v01.json";
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function audioConstructor() {
  if (typeof window !== "undefined" && typeof window.Audio === "function") return window.Audio;
  if (typeof Audio === "function") return Audio;
  return null;
}

function cleanupAudioElement() {
  if (!state.audioElement) {
    state.audioAsset = null;
    return;
  }
  try {
    state.audioElement.pause();
    state.audioElement.removeAttribute?.("src");
    state.audioElement.load?.();
  } catch {
    // Ignore cleanup failures; stopping playback should remain best-effort.
  }
  state.audioElement = null;
  state.audioAsset = null;
}

// The GitHub Pages mirror stays under the 1 GB site limit by streaming MP3s
// from jsDelivr (which reads the mirror repo directly). Other hosts serve
// same-origin files.
function resolveAudioSrc(src) {
  const hostname = typeof window !== "undefined" && window.location ? window.location.hostname : "";
  if (hostname === "heatherwww.github.io") {
    return `https://cdn.jsdelivr.net/gh/Heatherwww/cn-audio-walks@main/${src}`;
  }
  return src;
}

function playAudioAsset(asset, options) {
  if (!asset?.src) return false;
  const AudioCtor = audioConstructor();
  if (!AudioCtor) return false;

  window.speechSynthesis?.cancel();
  clearVoiceTimers();
  cleanupAudioElement();

  const audio = new AudioCtor(resolveAudioSrc(asset.src));
  state.audioElement = audio;
  state.audioAsset = asset;
  state.audioSourceMode = "asset";
  state.isPlaying = true;
  state.routeTourCompleted = false;
  state.playbackMode = options.mode;
  state.progress = 0;
  state.playStartedAt = Date.now();
  state.playDurationSeconds = asset.durationSeconds || options.durationSeconds;
  state.activeSegmentIndex = 0;
  audio.playbackRate = state.playbackRate;
  if (state.pausedSeconds && options.mode === "intro") {
    audio.currentTime = state.pausedSeconds;
    state.playStartedAt = Date.now() - state.pausedSeconds * 1000;
    state.progress = (state.pausedSeconds / state.playDurationSeconds) * 100;
    state.pausedSeconds = 0;
  }
  ensureMusicElement();
  syncMusicPlayback();

  const routeId = options.route.id;
  const stopIndex = options.stopIndex;
  const isIntro = options.mode === "intro";
  audio.preload = "auto";
  audio.addEventListener?.("ended", () => {
    if (isIntro) finishIntroPlayback(routeId, stopIndex);
    else finishStopPlayback(routeId, stopIndex);
  });
  audio.addEventListener?.("error", () => {
    const fallback = options.fallback;
    cleanupAudioElement();
    if (typeof fallback === "function") fallback();
  });

  window.clearInterval(state.tick);
  state.tick = window.setInterval(() => {
    const elapsedSeconds = playbackElapsedSeconds();
    state.progress = Math.min(100, (elapsedSeconds / state.playDurationSeconds) * 100);
    state.activeSegmentIndex = isIntro
      ? activeSegmentIndexForSegments(buildRouteIntroSegments(options.route, stopIndex))
      : activeSegmentIndexForElapsed(options.route, options.route.stops[stopIndex], stopIndex);
    updateProgressOnly();
    updatePlaybackStatusOnly();
  }, 1000);

  const playAttempt = audio.play?.();
  if (playAttempt?.catch) {
    playAttempt.catch(() => {
      const fallback = options.fallback;
      cleanupAudioElement();
      if (typeof fallback === "function") fallback();
    });
  }

  render();
  return true;
}

function speakCurrentStop() {
  const route = getRoute();
  const asset = audioPlaybackAsset(route, state.stopIndex, "stop");
  if (playAudioAsset(asset, {
    mode: "stop",
    route,
    stopIndex: state.stopIndex,
    durationSeconds: stopAudioMinutes(route, state.stopIndex) * 60,
    fallback: speakCurrentStopWithSpeech
  })) return;
  speakCurrentStopWithSpeech();
}

function speakCurrentStopWithSpeech(startOffsetSeconds = 0) {
  const stop = getStop();
  const route = getRoute();
  const routeId = route.id;
  const stopIndex = state.stopIndex;
  const stopMinutes = stopAudioMinutes(route, state.stopIndex);
  const segments = buildStopAudioSegments(route, stop, state.stopIndex);
  const offsetMs = Math.max(0, startOffsetSeconds * 1000);
  window.speechSynthesis?.cancel();
  clearVoiceTimers();
  cleanupAudioElement();
  state.isPlaying = true;
  state.routeTourCompleted = false;
  state.playbackMode = "stop";
  state.audioSourceMode = "speech";
  state.progress = 0;
  state.playStartedAt = Date.now() - offsetMs;
  state.playDurationSeconds = stopMinutes * 60;
  ensureMusicElement();
  syncMusicPlayback();
  let startedImmediate = false;
  segments.forEach((segment, index) => {
    const text = segment.text;
    const startMs = segment.minute * 60 * 1000 - offsetMs;
    if (startMs <= 0) {
      if (segments[index + 1] && segments[index + 1].minute * 60 * 1000 - offsetMs > 0) {
        state.activeSegmentIndex = index;
        speakText(text);
        startedImmediate = true;
      } else if (!segments[index + 1] && !startedImmediate) {
        state.activeSegmentIndex = index;
        speakText(text);
        startedImmediate = true;
      }
      return;
    }
    state.voiceTimers.push(window.setTimeout(() => {
      state.activeSegmentIndex = index;
      updatePlaybackStatusOnly();
      speakText(text);
    }, startMs));
  });
  window.clearInterval(state.tick);
  state.tick = window.setInterval(() => {
    const elapsedSeconds = (Date.now() - state.playStartedAt) / 1000;
    state.progress = Math.min(100, (elapsedSeconds / state.playDurationSeconds) * 100);
    state.activeSegmentIndex = activeSegmentIndexForElapsed(route, stop, state.stopIndex);
    updateProgressOnly();
    updatePlaybackStatusOnly();
    if (state.progress >= 100) {
      finishStopPlayback(routeId, stopIndex);
    }
  }, 1000);
  render();
}

function speakRouteIntro() {
  const route = getRoute();
  const asset = audioPlaybackAsset(route, state.stopIndex, "intro");
  if (playAudioAsset(asset, {
    mode: "intro",
    route,
    stopIndex: state.stopIndex,
    durationSeconds: routeIntroDurationMinutes(route, state.stopIndex) * 60,
    fallback: speakRouteIntroWithSpeech
  })) return;
  speakRouteIntroWithSpeech();
}

function speakRouteIntroWithSpeech(startOffsetSeconds = 0) {
  const route = getRoute();
  const routeId = route.id;
  const startIndex = state.stopIndex;
  const introMinutes = routeIntroDurationMinutes(route, startIndex);
  const segments = buildRouteIntroSegments(route, startIndex);
  const offsetMs = Math.max(0, startOffsetSeconds * 1000);
  window.speechSynthesis?.cancel();
  clearVoiceTimers();
  cleanupAudioElement();
  state.isPlaying = true;
  state.routeTourCompleted = false;
  state.playbackMode = "intro";
  state.audioSourceMode = "speech";
  state.progress = 0;
  state.playStartedAt = Date.now() - offsetMs;
  state.playDurationSeconds = introMinutes * 60;
  ensureMusicElement();
  syncMusicPlayback();
  let startedImmediate = false;
  segments.forEach((segment, index) => {
    const text = segment.text;
    const startMs = segment.minute * 60 * 1000 - offsetMs;
    if (startMs <= 0) {
      if (segments[index + 1] && segments[index + 1].minute * 60 * 1000 - offsetMs > 0) {
        state.activeSegmentIndex = index;
        speakText(text);
        startedImmediate = true;
      } else if (!segments[index + 1] && !startedImmediate) {
        state.activeSegmentIndex = index;
        speakText(text);
        startedImmediate = true;
      }
      return;
    }
    state.voiceTimers.push(window.setTimeout(() => {
      state.activeSegmentIndex = index;
      updatePlaybackStatusOnly();
      speakText(text);
    }, startMs));
  });
  window.clearInterval(state.tick);
  state.tick = window.setInterval(() => {
    const elapsedSeconds = (Date.now() - state.playStartedAt) / 1000;
    state.progress = Math.min(100, (elapsedSeconds / state.playDurationSeconds) * 100);
    state.activeSegmentIndex = activeSegmentIndexForSegments(segments);
    updateProgressOnly();
    updatePlaybackStatusOnly();
    if (state.progress >= 100) {
      finishIntroPlayback(routeId, startIndex);
    }
  }, 1000);
  render();
}

function stopAudio(shouldRender = true, keepRouteTour = false) {
  window.speechSynthesis?.cancel();
  clearVoiceTimers();
  cleanupAudioElement();
  window.clearInterval(state.tick);
  state.tick = null;
  state.isPlaying = false;
  state.progress = 0;
  state.playStartedAt = 0;
  state.playDurationSeconds = 0;
  state.activeSegmentIndex = 0;
  state.playbackMode = "stop";
  state.audioSourceMode = "speech";
  if (!keepRouteTour) {
    state.routeTourMode = false;
    state.routeTourCompleted = false;
  }
  syncMusicPlayback();
  if (shouldRender) render();
}

function clearVoiceTimers() {
  state.voiceTimers.forEach((timer) => window.clearTimeout(timer));
  state.voiceTimers = [];
}

function speakText(text) {
  if (!("speechSynthesis" in window) || !("SpeechSynthesisUtterance" in window)) return;
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "zh-CN";
  utterance.rate = Math.max(0.5, Math.min(2, 0.86 * state.playbackRate));
  utterance.pitch = 0.95;
  window.speechSynthesis.speak(utterance);
}

function buildTimelineOffsets(minutes) {
  const lastMinute = Math.max(1, minutes - 1);
  const base = [0, 1, 2, 3, 5, 6, 7, 8, 10, 11];
  const scale = Math.min(1, minutes / 12);
  return [...new Set(base.map((minute) => Math.max(0, Math.min(lastMinute, Math.round(minute * scale)))))].sort((a, b) => a - b);
}

function narrationSeed(route, index) {
  const text = `${route.id}-${index}`;
  let hash = 0;
  for (let i = 0; i < text.length; i += 1) {
    hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  }
  return hash;
}

function estimateSpeechSeconds(text) {
  const clean = String(text).replace(/[\s\p{P}\p{S}]/gu, "");
  return clean.length / 4;
}

function buildStopAudioSegments(route, stop, index) {
  const anchor = contentAnchorForStop(route, index);
  const notes = Array.isArray(stop.notes) ? stop.notes.filter(Boolean) : [];
  const seed = narrationSeed(route, index);
  const pick = (pool, shift = 0) => pool[(seed + shift) % pool.length];

  const openers = [
    `到了，${stop.title}。${stop.location}。就站在这儿，别急着走，先让眼睛适应几秒钟。`,
    `这一站是${stop.title}。先找好位置：${stop.location}。站定就好，我跟你说怎么看。`,
    `往前走就是${stop.title}。${stop.location}。接下来几分钟交给我。`,
    `${stop.location}。好，就这儿。这里是${stop.title}——我先不说它多有名，你先自己看十秒钟。`,
    `我们到${stop.title}了。${stop.location}。站好了再听，不赶时间。`,
    `来，${stop.title}。${stop.location}。我先带你用眼睛走一圈，再讲它的来历。`,
    `${stop.title}到了。${stop.location}。今天人多人少都没关系，你听我的节奏来。`,
    `这里是${stop.title}。${stop.location}。先别拍照，最好的一张照片要等听完才知道在哪儿。`,
    `停一下，${stop.title}就在这儿。${stop.location}。这一站值得多花几分钟。`,
    `欢迎到${stop.title}。${stop.location}。你先环顾一圈，我在旁边等你看完。`
  ];
  const lookFirst = [
    `${stop.cue}。先只看大的轮廓，别管细节，细节我等下指给你。`,
    `第一件事：${stop.cue}。别的先不看。`,
    `眼睛先往这儿放：${stop.cue}。`,
    `${stop.cue}。先看整体，细节一会儿再说。`,
    `先看这个：${stop.cue}。`,
    `${stop.cue}。大形先看清楚，小细节随后补。`,
    `把注意力先放在这儿：${stop.cue}。`,
    `${stop.cue}。先看个大概，细的地方我一会儿指给你。`
  ];
  const mainTell = [
    `现在说正经的。${stop.script}`,
    `好了，重点来了。${stop.script}`,
    `说说你眼前这东西。${stop.script}`
  ];

  const detailText = notes[0] || `再凑近一点看：${stop.cue}。`;
  const storyText = notes[1] ? `${notes[1]}${anchor ? ` 一个考证过的背景：${anchor}` : ""}` : (anchor ? `一个考证过的背景：${anchor}` : `${route.theme}，在这条路线里就落在你眼前这一处。`);
  const extraText = notes[2] || (anchor && notes[1] ? "" : `同行的人可以互相问问：你先看的是哪儿？答案通常不一样。`);

  const dwellLines = [
    "给你两分钟自己看。看完不用着急，我还在。",
    "两分钟你自己看，别急。",
    "这段留给你，两分钟，看完我们继续。",
    "你看两分钟，我在旁边等。",
    "先看两分钟，一会儿我再讲。",
    "这两分钟归你。",
    "你慢慢看，两分钟就好。",
    "两分钟的时间，你自己看。"
  ];
  const photoLines = [
    "想拍就现在拍。一张全景、一张细节，拍完把手机收起来。",
    "拍两张吧，全景和细节各一张。",
    "这里是这条线最适合拍照的地方，给你两分钟。",
    "要拍照的话就是这儿了，拍完我们继续。",
    "这个角度值得留一张。拍完我们就走。",
    "给你拍两张的时间，拍好我们就往前。",
    "现在可以拍了，拍完自己把手机收好。",
    "这一站适合拍照。一张全貌，一张你最喜欢的细节。"
  ];
  const tellLines = [
    "讲讲你眼前这个东西。",
    "说正经的了。",
    "现在讲它。",
    "来说这个。",
    "你听这段。",
    "说说它。",
    "讲正题。",
    "这一段你听一下。"
  ];
  const ambientLines = [
    "今天这天气，站一会儿正好。",
    "站久了脚酸，正好靠一下。",
    "你看旁边的人，大家都不赶时间。",
    "这会儿风不大，声音能听得很清楚。",
    "我上次来的时候，这里还在修。",
    "这条道我走过很多回，每回看的重点都不一样。",
    "说实话，第一次来我也没看出门道。",
    "你猜这地方多少年了？先别查，听完就知道。"
  ];
  const finalLines = [
    `好了，出发。${stop.next}`,
    `走，${stop.next}`,
    `听得差不多了，${stop.next}`,
    `这站就这样。${stop.next}`,
    `往前吧，${stop.next}`,
    `走。${stop.next}`,
    `差不多了，${stop.next}`,
    `走吧，${stop.next}`
  ];

  const angleLines = [
    "旁边不挤的话，往侧面挪几步再看一次。位置变了，看到的东西也跟着变。",
    "要是方便，绕到侧面再看一眼，有些细节只有侧着才露出来。",
    "可以往边上挪几步换个位置看，远近高低各有一点不一样。",
    "退一步，或者往旁边让半步，看到的会比正对着更多。",
    "换个站位再看一次。你刚才站的地方和现在看到的东西，可以对一对。"
  ];
  const lastLookLines = [
    "走之前别急着转身，抬眼把这里再扫一圈，刚才说的那些都在你眼前摆着。",
    "走之前再看一眼。刚才听的那些，现在都在你眼前。",
    "要离开之前，回头再扫一眼，这一站的内容都在那儿了。",
    "转身之前，把这里再看一圈。刚才讲的细节，你自己找找看。",
    "走之前最后看一眼，刚才听到的，现在自己认领一下。"
  ];

  const dwellText = pick(dwellLines, 7) + (seed % 3 === 0 ? pick(ambientLines, 11) : "");
  const photoText = pick(photoLines, 13) + (seed % 4 === 1 ? pick(ambientLines, 17) : "");

  const coreSegments = [
    { label: "到站", text: pick(openers) },
    { label: "先看", text: pick(lookFirst, 3) },
    { label: "慢慢看", isPause: true, text: dwellText },
    { label: "讲给你听", text: `${pick(tellLines, 5)}${stop.script}` },
    { label: "看细节", text: detailText },
    { label: "拍两张", isPause: true, text: photoText },
    { label: "往事", text: storyText },
    { label: "换个角度", text: `${extraText}${pick(angleLines, 23)}` },
    { label: "最后一眼", text: pick(lastLookLines, 29) }
  ];
  const finalSegment = {
    label: "下一站",
    text: pick(finalLines, 19)
  };

  const chain = coreSegments.slice();
  const optionalDrop = ["换个角度", "看细节", "最后一眼"][seed % 3];
  const dropIndex = chain.findIndex((segment) => segment.label === optionalDrop);
  if (dropIndex > 0) chain.splice(dropIndex, 1);

  const segments = [];
  let cursor = 0;
  const gapMinutes = 0.03;
  chain.concat([finalSegment]).forEach((source) => {
    const minute = cursor;
    segments.push({ minute, ...source });
    const dwellMinutes = source.isPause ? 2 : 0;
    cursor += estimateSpeechSeconds(source.text) / 60 + (dwellMinutes || gapMinutes);
  });
  return segments;
}

function formatMinuteMark(minute) {
  const whole = Math.floor(minute);
  const seconds = Math.round((minute - whole) * 60);
  return `${whole}:${String(seconds).padStart(2, "0")}`;
}

function formatClock(seconds) {
  const safeSeconds = Math.max(0, Math.floor(seconds || 0));
  const minutes = Math.floor(safeSeconds / 60);
  const remainder = String(safeSeconds % 60).padStart(2, "0");
  return `${minutes}:${remainder}`;
}

function playbackElapsedSeconds() {
  if (!state.isPlaying || !state.playStartedAt) return 0;
  if (state.audioElement) return Math.min(state.playDurationSeconds, state.audioElement.currentTime || 0);
  return Math.min(state.playDurationSeconds, (Date.now() - state.playStartedAt) / 1000);
}

function activeSegmentIndexForSegments(segments) {
  if (!state.isPlaying) return 0;
  const elapsedMinutes = playbackElapsedSeconds() / 60;
  let activeIndex = 0;
  segments.forEach((segment, segmentIndex) => {
    if (segment.minute <= elapsedMinutes) activeIndex = segmentIndex;
  });
  return activeIndex;
}

function activeSegmentIndexForElapsed(route, stop, index) {
  return activeSegmentIndexForSegments(buildStopAudioSegments(route, stop, index));
}

function pauseSegmentsForStop(route, stop, index) {
  return buildStopAudioSegments(route, stop, index).filter((segment) => segment.isPause);
}

function renderLongTranscript(route, stop, index) {
  return buildStopAudioSegments(route, stop, index)
    .map((segment) => `<p class="${segment.isPause ? "transcript-pause" : ""}"><strong class="transcript-mark" data-seek="${segment.minute * 60}" onclick="seekPlayback(${segment.minute * 60})" role="button" tabindex="0" aria-label="跳到 ${formatMinuteMark(segment.minute)}">${formatMinuteMark(segment.minute)} ${segment.label}。</strong>${segment.text}</p>`)
    .join("");
}

function renderPlaybackStatus(route, stop) {
  const introMode = state.introSelected || state.playbackMode === "intro";
  const segments = introMode
    ? buildRouteIntroSegments(route, state.stopIndex)
    : buildStopAudioSegments(route, stop, state.stopIndex);
  const activeIndex = state.isPlaying
    ? Math.min(state.activeSegmentIndex, segments.length - 1)
    : 0;
  const segment = segments[activeIndex] || segments[0];
  const next = segments[activeIndex + 1];
  const nextStopLabel = `第 ${state.stopIndex + 1} 站 · ${stop.title}`;
  const modeLabel = introMode ? "路线开场中" : state.isPlaying ? "正在播放" : "准备播放";
  const guideText = introMode
    ? "先听起点、路线走法和第一站提示，不用急着往前走。"
    : segment.isPause
    ? "这一段留给你驻足浏览和拍照，不用暂停音频。"
    : "跟着声音看现场，先确认站位，再移动视线。";
  const nextText = introMode
    ? next
      ? `下一段 ${formatMinuteMark(next.minute)} · ${next.label}；开场结束后进入${nextStopLabel}`
      : `开场结束后进入${nextStopLabel}`
    : next
      ? `下一段 ${formatMinuteMark(next.minute)} · ${next.label}`
      : `本点结束后：${stop.next}`;
  const rhythmLabel = introMode ? `${route.title}路线开场章节状态` : `${stop.title}播放中的章节状态`;
  return `
    <div class="live-segment${state.isPlaying ? " playing" : ""}${segment.isPause ? " dwell" : ""}" data-live-segment>
      <div class="live-segment-head">
        <span>${modeLabel}</span>
        <strong>${formatMinuteMark(segment.minute)} · ${segment.label}</strong>
      </div>
      <p>${guideText}</p>
      <div class="live-segment-next">
        ${nextText}
      </div>
      <div class="playback-rhythm" aria-label="${rhythmLabel}">
        ${segments
          .map(
            (item, index) => `
              <span class="rhythm-dot seekable${index === activeIndex ? " active" : ""}${item.isPause ? " pause" : ""}" data-seek="${item.minute * 60}" onclick="seekPlayback(${item.minute * 60})" role="button" tabindex="0" aria-label="跳到 ${formatMinuteMark(item.minute)} ${item.label}">
                <b>${formatMinuteMark(item.minute)}</b>${item.label}
              </span>
            `
          )
          .join("")}
      </div>
    </div>
  `;
}

function toggleAudio() {
  if (state.isPlaying) {
    stopAudio();
  } else {
    speakCurrentStop();
  }
}

function seekPlayback(seconds) {
  const target = Math.max(0, Math.min((state.playDurationSeconds || 1) - 0.5, Number(seconds) || 0));
  const introContext = state.introSelected || state.playbackMode === "intro";
  if (!state.isPlaying) {
    if (introContext) {
      speakRouteIntro();
    } else {
      speakCurrentStop();
    }
  }
  if (!state.playDurationSeconds) return;
  if (state.audioElement) {
    state.audioElement.currentTime = target;
    state.progress = (target / state.playDurationSeconds) * 100;
    state.activeSegmentIndex = introContext
      ? activeSegmentIndexForSegments(buildRouteIntroSegments(getRoute(), state.stopIndex))
      : activeSegmentIndexForElapsed(getRoute(), getStop(), state.stopIndex);
    updateProgressOnly();
    updatePlaybackStatusOnly();
    return;
  }
  if (introContext) {
    speakRouteIntroWithSpeech(target);
  } else {
    speakCurrentStopWithSpeech(target);
  }
}

function seekBarEvent(event) {
  if (!state.isPlaying) return;
  const rect = event.currentTarget.getBoundingClientRect();
  if (!rect.width) return;
  const fraction = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
  seekPlayback(fraction * state.playDurationSeconds);
}

function setPlaybackRate(rate) {
  const value = Number(rate);
  if (!value) return;
  state.playbackRate = value;
  if (state.audioElement) state.audioElement.playbackRate = value;
  render();
}

function ensureMusicElement() {
  const cityIndex = Math.max(0, data.cities.findIndex((city) => city.id === state.cityId));
  const track = (cityIndex % 6) + 1;
  const src = resolveAudioSrc(`audio-assets/ambient/${track}.mp3`);
  if (state.musicElement) {
    if (state.musicTrack !== track) {
      state.musicElement.src = src;
      state.musicTrack = track;
      state.musicElement.load?.();
    }
    return state.musicElement;
  }
  const AudioCtor = audioConstructor();
  if (!AudioCtor) return null;
  const music = new AudioCtor(src);
  music.loop = true;
  music.volume = 0.12;
  music.preload = "auto";
  state.musicElement = music;
  state.musicTrack = track;
  return music;
}

function syncMusicPlayback() {
  const music = state.musicElement;
  if (!music) return;
  if (state.isPlaying && state.musicOn) {
    const attempt = music.play?.();
    if (attempt?.catch) attempt.catch(() => {});
  } else {
    music.pause();
  }
}

function toggleMusic() {
  state.musicOn = !state.musicOn;
  if (state.musicOn) ensureMusicElement();
  syncMusicPlayback();
  render();
}

function startRouteTour() {
  const shouldRestartRoute = state.routeTourCompleted;
  stopAudio(false);
  if (shouldRestartRoute) state.stopIndex = 0;
  state.view = "route";
  state.routeTourMode = true;
  state.routeTourCompleted = false;
  state.tab = "info";
  const shouldPlayIntro = shouldRestartRoute || Boolean(nextStop(getRoute()));
  state.introSelected = shouldPlayIntro;
  if (shouldPlayIntro) {
    speakRouteIntro();
  } else {
    speakCurrentStop();
  }
}

function toggleRouteTour() {
  if (state.routeTourMode) {
    stopAudio();
  } else {
    startRouteTour();
  }
}

function finishStopPlayback(routeId, stopIndex) {
  if (!state.routeTourMode || state.routeId !== routeId) {
    stopAudio(false);
    render();
    return;
  }

  const route = getRoute();
  if (stopIndex < route.stops.length - 1) {
    stopAudio(false, true);
    state.stopIndex = stopIndex + 1;
    state.introSelected = false;
    state.tab = "info";
    speakCurrentStop();
    return;
  }

  stopAudio(false);
  state.routeTourCompleted = true;
  render();
}

function finishIntroPlayback(routeId, startIndex) {
  if (!state.routeTourMode || state.routeId !== routeId) {
    stopAudio(false);
    render();
    return;
  }

  stopAudio(false, true);
  state.stopIndex = startIndex;
  state.introSelected = false;
  state.tab = "info";
  speakCurrentStop();
}

function goStop(delta) {
  const route = getRoute();
  const nextIndex = Math.max(0, Math.min(route.stops.length - 1, state.stopIndex + delta));
  if (state.routeTourMode) {
    stopAudio(false, true);
    state.stopIndex = nextIndex;
    state.introSelected = false;
    state.tab = "info";
    speakCurrentStop();
    return;
  }
  setStop(nextIndex);
}

function nextStop(route) {
  return route.stops[state.stopIndex + 1] || null;
}

function routeProgressPercent(route) {
  return Math.round(((state.stopIndex + 1) / route.stops.length) * 100);
}

function playButtonLabel() {
  if (state.routeTourMode) return `${icons.pause}停止整线`;
  return state.isPlaying ? `${icons.pause}停止讲解` : `${icons.play}播放讲解`;
}

function updateProgressOnly() {
  const fill = document.querySelector(".progress-fill");
  if (fill) fill.style.width = `${state.progress}%`;
  const elapsed = document.querySelector(".progress-elapsed");
  if (elapsed) elapsed.textContent = formatClock(playbackElapsedSeconds());
}

function updatePlaybackStatusOnly() {
  const liveSegment = document.querySelector("[data-live-segment]");
  if (liveSegment) liveSegment.outerHTML = renderPlaybackStatus(getRoute(), getStop());
}

function routePath(points) {
  return points.map((xy, index) => `${index === 0 ? "M" : "L"} ${xy[0]} ${xy[1]}`).join(" ");
}

function audioMinutes(route) {
  return Math.round(routeIntroDurationMinutes(route, 0) + routeStopsAudioMinutes(route));
}

function routeStopsAudioMinutes(route) {
  return route.stops.reduce((sum, _, index) => sum + stopAudioMinutes(route, index), 0);
}

function audioDurationLabel(route) {
  return `${audioMinutes(route)} 分钟`;
}

function minutesFromDuration(value) {
  const text = String(value || "");
  const hourMatch = text.match(/([\d.]+)\s*小时/);
  const minuteMatch = text.match(/([\d.]+)\s*分钟/);
  let total = 0;
  if (hourMatch) total += Math.round(Number(hourMatch[1]) * 60);
  if (minuteMatch) total += Math.round(Number(minuteMatch[1]));
  return total || null;
}

function visitMinutes(route) {
  return minutesFromDuration(route.duration) || audioMinutes(route);
}

function visitDurationLabel(route) {
  return route.duration || `${visitMinutes(route)} 分钟`;
}

function stopAudioMinutes(route, index) {
  const segments = buildStopAudioSegments(route, route.stops[index], index);
  const last = segments[segments.length - 1];
  return last.minute + estimateSpeechSeconds(last.text) / 60 + 0.1;
}

function stopAudioDurationLabel(route, index) {
  return `${Math.round(stopAudioMinutes(route, index))} 分钟`;
}

function audioAssetDurationLabel(asset) {
  if (!asset?.durationSeconds) return "";
  return `约 ${Math.round(asset.durationSeconds / 60)} 分钟`;
}

function currentPlaybackDurationLabel(route) {
  const mode = state.introSelected ? "intro" : state.playbackMode;
  const asset = audioPlaybackAsset(route, state.stopIndex, mode);
  if (asset) return `${audioAssetDurationLabel(asset)} · MP3`;
  if (mode === "intro") {
    return routeIntroDurationLabel(route, state.stopIndex);
  }
  return stopAudioDurationLabel(route, state.stopIndex);
}

function currentAudioSourceInfo(route) {
  const mode = state.isPlaying ? state.playbackMode : "stop";
  const asset = audioPlaybackAsset(route, state.stopIndex, mode);
  return {
    label: audioPlaybackSourceLabel(route, state.stopIndex, mode),
    detail: asset ? `${asset.label} · ${audioAssetDurationLabel(asset)}` : "未生成音频文件时，使用浏览器语音按章节朗读",
    hasAsset: Boolean(asset)
  };
}

function routeViewBox(points) {
  const xs = points.map((xy) => xy[0]);
  const ys = points.map((xy) => xy[1] - 170);
  const minX = Math.max(10, Math.min(...xs) - 170);
  const maxX = Math.min(950, Math.max(...xs) + 170);
  // No lower clamp on minY: real-layout points can sit near the canvas top
  // (y≈170), and clamping to 0 would slice their circles in half.
  const minY = Math.min(...ys) - 170;
  const maxY = Math.min(680, Math.max(...ys) + 110);
  return {
    value: `${Math.round(minX)} ${Math.round(minY)} ${Math.round(maxX - minX)} ${Math.round(maxY - minY)}`,
    minX,
    minY,
    maxX,
    maxY,
    noteX: Math.round(minX + 26),
    noteY: Math.round(maxY - 22)
  };
}

function mapLabel(x, y, text, className = "map-landmark") {
  return `<text class="${className}" x="${x}" y="${y}">${text}</text>`;
}

function mapBuilding(x, y, width, height, text, className = "map-building") {
  return `
    <rect class="${className}" x="${x}" y="${y}" width="${width}" height="${height}" rx="8"></rect>
    ${mapLabel(x + 10, y + Math.min(height - 10, 24), text, "map-building-label")}
  `;
}

function mapCourtyard(x, y, width, height, text) {
  return `
    <rect class="map-courtyard" x="${x}" y="${y}" width="${width}" height="${height}" rx="14"></rect>
    ${mapLabel(x + 12, y + 26, text, "map-building-label")}
  `;
}

function mapPhotoZone(x, y, width, height, text) {
  return `
    <rect class="map-photo-zone" x="${x}" y="${y}" width="${width}" height="${height}" rx="999"></rect>
    ${mapLabel(x + 12, y + 23, text, "map-small-label")}
  `;
}

