function renderMap(route) {
  const layout = layoutFor(route);
  const points = mapPoints(route);
  const path = routePath(points);
  const viewBox = routeViewBox(points);
  const currentXY = points[state.stopIndex];
  const hereX = Math.min(820, currentXY[0] + 34);
  const hereY = Math.max(76, currentXY[1] - 42);
  const first = points[0];
  const second = points[1] || [first[0], first[1] + 1];
  const dirX = first[0] - second[0];
  const dirY = first[1] - second[1];
  const dirLen = Math.hypot(dirX, dirY) || 1;
  // Place the intro point perpendicular to the route direction so it never
  // sits on top of stop 1; flip sides if the first choice leaves the canvas.
  const perpX = (-dirY / dirLen) * 78;
  const perpY = (dirX / dirLen) * 78;
  let introX = first[0] + perpX;
  let introY = first[1] + perpY;
  if (introX < 70 || introX > 890 || introY < 90 || introY > 610) {
    introX = first[0] - perpX;
    introY = first[1] - perpY;
  }
  introX = Math.max(60, Math.min(900, introX));
  introY = Math.max(84, Math.min(614, introY));
  const labels = route.stops
    .map((stop, index) => {
      const xy = points[index];
      const active = index === state.stopIndex && !state.introSelected ? " active" : "";
      // Label sits right of the circle, vertically centered; only the bottom
      // edge flips it above-left so it stays inside the canvas.
      const yLabel = xy[1] > 610 ? xy[1] - 30 : xy[1] + 5;
      return `
        <g class="poi-button${active}" role="button" tabindex="0" data-stop="${index}" onclick="selectStopAndPlay(${index})" aria-label="${stop.title}">
          <circle cx="${xy[0]}" cy="${xy[1]}" r="21"></circle>
          <text x="${xy[0]}" y="${xy[1] + 1}">${index + 1}</text>
        </g>
        <text class="poi-label" x="${xy[0] + 28}" y="${yLabel}">${stop.title}</text>
      `;
    })
    .join("");
  // Compass rides inside the visible viewBox (it is drawn in viewBox space,
  // not in the shifted map-drawing space), otherwise it gets clipped on routes
  // whose stops sit far right or low on the canvas.
  const compassX = viewBox.maxX - 48;
  const compassY = viewBox.minY + 48;

  return `
    <svg class="route-map" viewBox="${viewBox.value}" role="img" aria-label="${route.title}路线地图">
      <defs>
        <filter id="mapWobble" x="-5%" y="-5%" width="110%" height="110%">
          <feTurbulence type="fractalNoise" baseFrequency="0.012" numOctaves="2" seed="7" result="noise" />
          <feDisplacementMap in="SourceGraphic" in2="noise" scale="7" />
        </filter>
        <linearGradient id="mapSky" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stop-color="#f2eee0"></stop>
          <stop offset="1" stop-color="#eef3ed"></stop>
        </linearGradient>
      </defs>
      <rect x="-200" y="-400" width="1360" height="1480" fill="url(#mapSky)"></rect>
      <g class="map-compass">
        <circle cx="${compassX}" cy="${compassY}" r="30" class="map-compass-ring"></circle>
        <path d="M${compassX - 18} ${compassY - 6} l18 -34 l18 34 l-18 -8Z"></path>
        <text x="${compassX}" y="${compassY + 20}">N</text>
      </g>
      <g class="map-drawing" transform="translate(0 -170)">
        <g filter="url(#mapWobble)">
          ${layout ? renderLayoutBackdrop(route, layout) : mapBackdrop(route.id)}
        </g>
        <g filter="url(#mapWobble)">
          <path class="route-line-shadow" d="${path}"></path>
          <path class="route-line" d="${path}"></path>
          <path class="route-line-dash" d="${path}"></path>
        </g>
        ${labels}
        <g class="poi-button intro-point${state.introSelected ? " active" : ""}" role="button" tabindex="0" data-intro onclick="selectIntroAndPlay()" aria-label="路线开场">
          <circle cx="${introX}" cy="${introY}" r="19"></circle>
          <text x="${introX}" y="${introY + 1}">起</text>
        </g>
        <text class="poi-label" x="${introX + 26}" y="${introY + 5}">路线开场</text>
        <g class="map-here">
          <path d="M${hereX} ${hereY} h92 a18 18 0 0 1 18 18 v0 a18 18 0 0 1 -18 18 h-92 a18 18 0 0 1 -18 -18 v0 a18 18 0 0 1 18 -18Z"></path>
          <text x="${hereX + 46}" y="${hereY + 19}">你在这里</text>
        </g>
      </g>
      <text class="map-note" x="${viewBox.noteX}" y="${viewBox.noteY}">${route.start} → ${route.end}</text>
    </svg>
  `;
}

function renderBrand() {
  return `
    <div class="brand">
      <div class="brand-mark">${icons.compass}</div>
      <div>
        <h1>山河听路</h1>
        <p>China Audio Walks</p>
      </div>
    </div>
  `;
}

function renderHomeView() {
  return `
    <main class="home-view">
      <header class="home-hero">
        ${renderBrand()}
        <p class="home-tagline">先选城市，再选一条路线，然后跟着地图一站一站听。像 Rick Steves Audio Europe 一样的现场音频导览。</p>
      </header>
      <div class="section-label">选择目的地 · ${data.cities.length} 个城市</div>
      <div class="city-grid">
        ${data.cities
          .map((city) => {
            const stopCount = city.routes.reduce((sum, route) => sum + route.stops.length, 0);
            return `
              <button class="city-tile" data-city="${city.id}" onclick="setCity('${city.id}')">
                <span class="city-tile-name">${city.name}</span>
                <span class="city-tile-meta">${city.subtitle}</span>
                <span class="city-tile-stats">${city.routes.length} 条路线 · ${stopCount} 个点位</span>
              </button>
            `;
          })
          .join("")}
      </div>
    </main>
  `;
}

function renderCityView(city) {
  return `
    <main class="city-view">
      <nav class="crumb" aria-label="返回上一级">
        <button class="crumb-back" data-view="cities" onclick="showCities()">← 全部城市</button>
      </nav>
      <header class="city-hero">
        <p class="eyebrow">目的地 · ${city.routes.length} 个景点/片区</p>
        <h2>${city.name}</h2>
        <p class="city-summary">${city.overview}</p>
      </header>
      <section class="city-intro-card${state.isPlaying ? " playing" : ""}" aria-label="${city.name}城市开场">
        <div class="sheet-kicker">城市开场 · 约 ${Math.max(1, Math.ceil(estimateSpeechSeconds(cityIntros[city.id] || city.overview) / 60))} 分钟</div>
        <h3>${city.name}这座城</h3>
        <p class="sheet-copy">${cityIntros[city.id] || city.overview}</p>
        <div class="player-controls player-controls-row">
          <button class="primary-button" data-play-city-intro onclick="playCityIntro()">${state.isPlaying ? icons.pause + "暂停城市开场" : icons.play + "播放城市开场"}</button>
        </div>
      </section>
      <div class="section-label">${city.name}可听的景点/片区 · 选择一条路线进入地图</div>
      <div class="route-card-list">
        ${routePickerItems(city, getRoute())
          .map(
            (item) => `
              <button class="sight-card${item.id === state.routeId ? " active" : ""}" data-route="${item.id}" onclick="setRoute('${item.id}')">
                <span class="sight-card-top">
                  <span class="sight-title">${item.title}</span>
                  <span class="sight-state">${audioDurationLabel(item)} 语音覆盖</span>
                </span>
                <span class="sight-theme">${item.theme}</span>
                <span class="sight-path">${item.start} → ${item.end}</span>
                <span class="sight-metrics">
                  <span>${icons.play}${audioDurationLabel(item)}</span>
                  <span>${icons.map}${item.stops.length} 点</span>
                  <span>${item.distance}</span>
                </span>
              </button>
            `
          )
          .join("")}
      </div>
    </main>
  `;
}

function renderReviewStrip(city, route) {
  const active = reviewCheckpoints.find((item) => item.cityId === city.id && item.routeId === route.id);
  return `
    <section class="review-strip" aria-label="发布前手机验收">
      <div class="review-strip-head">
        <span>发布前手机验收</span>
        <strong>${active ? `当前：${active.title}` : "选择一条验收路线"}</strong>
        <p>先走两条样例路线，确认点位点击、文字稿、驻足留白、语音提示和下一站指令，再进入公开发布。</p>
      </div>
      <div class="review-actions">
        ${reviewCheckpoints
          .map(
            (item) => `
              <a class="review-link${item.cityId === city.id && item.routeId === route.id ? " active" : ""}" href="${reviewCheckpointUrl(item)}">
                <span>${item.label}</span>
                <strong>${item.title}</strong>
                <small>${item.focus}</small>
              </a>
            `
          )
          .join("")}
        <span class="review-file">清单：qa-mobile-acceptance-cn-20260824-v01.md</span>
        <button class="review-export" data-library-download onclick="toggleLibraryDownload()">
          ${icons.download}
          ${state.libraryDownloaded ? "已导出全库包" : "导出全库制作包"}
        </button>
      </div>
      ${renderReviewChecklist(route)}
      ${renderReviewAudit(route)}
    </section>
  `;
}

function renderReviewChecklist(route) {
  const checked = reviewChecklistItems.filter((item) => state.reviewChecks.has(item.id)).length;
  const total = reviewChecklistItems.length;
  const complete = checked === total;
  return `
    <div class="review-checklist" aria-label="验收勾选清单">
      <div class="review-progress">
        <span>人工确认</span>
        <strong>${checked}/${total}</strong>
        <small>${complete ? "本地体验已标记通过，等待进入公开预览准备。" : "按手机实际走查逐项勾选，全部通过后再进入公开预览。"}</small>
      </div>
      <div class="review-checks">
        ${reviewChecklistItems
          .map((item) => {
            const isChecked = state.reviewChecks.has(item.id);
            const detail =
              item.id === "duration"
                ? `语音 ${audioDurationLabel(route)}，建议 ${visitDurationLabel(route)}`
                : item.detail;
            return `
              <button class="review-check${isChecked ? " checked" : ""}" data-review-check="${item.id}" onclick="toggleReviewCheck('${item.id}')" aria-pressed="${isChecked}">
                <span class="review-box" aria-hidden="true">${isChecked ? "✓" : ""}</span>
                <span class="review-check-copy">
                  <strong>${item.label}</strong>
                  <small>${detail}</small>
                </span>
              </button>
            `;
          })
          .join("")}
      </div>
    </div>
  `;
}

function renderReviewAudit(route) {
  return `
    <div class="review-audit" aria-label="${route.title}路线质检摘要">
      <div class="review-audit-head">
        <span>路线质检</span>
        <strong>${route.title}</strong>
      </div>
      <div class="review-audit-grid">
        ${routeQualitySummary(route)
          .map(
            (item) => `
              <span class="review-audit-item${item.ok ? " ok" : " warn"}">
                <b>${item.label}</b>
                <strong>${item.value}</strong>
                <small>${item.detail}</small>
              </span>
            `
          )
          .join("")}
      </div>
    </div>
  `;
}

function renderRouteView(city, route, stop) {
  return `
    <main class="route-view${state.reviewMode ? " review-main" : ""}">
      <nav class="crumb" aria-label="返回上一级">
        <button class="crumb-back" data-view="cities" onclick="showCities()">全部城市</button>
        <span class="crumb-sep">/</span>
        <button class="crumb-back" data-view="routes" onclick="showCityRoutes()">${city.name}</button>
        <span class="crumb-sep">/</span>
        <strong class="crumb-current">${route.title}</strong>
      </nav>
      ${state.reviewMode ? renderReviewStrip(city, route) : ""}
      <header class="route-hero">
        <div>
          <p class="eyebrow">${route.theme}</p>
          <h2>${route.title}</h2>
          <p class="route-hero-path">${route.start} → ${route.end} · ${route.distance}</p>
        </div>
        <div class="status-strip" aria-label="当前路线信息">
          <span class="status-pill">建议游览 ${visitDurationLabel(route)}</span>
          <span class="status-pill">语音覆盖 ${audioDurationLabel(route)}</span>
          <span class="status-pill">${route.stops.length} 个点位</span>
          <span class="status-pill">${route.bestTime}</span>
          <button class="download-toggle" data-download onclick="toggleDownload()">
            ${icons.download}
            ${state.downloaded.has(route.id) ? "已离线 · 导出" : "导出脚本"}
          </button>
        </div>
      </header>
      <section class="map-stage" aria-label="${route.title}景点地图">
        <p class="map-hint">点击地图上的编号点直接播放该站讲解，点击「起」点听路线开场。${route.mapNote}</p>
        <div class="map-wrap"><div class="map-scroll">${renderMap(route)}</div></div>
        ${renderRouteGuide(route, stop)}
      </section>
      ${state.routeTourCompleted ? renderRouteCompletion(route) : ""}
      ${state.introSelected ? renderIntroSheet(route) : renderStopSheet(route, stop)}
    </main>
  `;
}

function renderIntroSheet(route) {
  const segments = buildRouteIntroSegments(route, state.stopIndex);
  const isActiveIntro = state.playbackMode === "intro";
  const introAsset = audioPlaybackAsset(route, 0, "intro");
  return `
    <section class="stop-sheet intro-sheet${isActiveIntro ? " active" : ""}" aria-label="${route.title}路线开场">
      <div class="sheet-head">
        <div class="stop-index">${isActiveIntro ? "路线开场中" : "开始前先听"} · ${routeIntroDurationLabel(route, state.stopIndex)}</div>
        <h3>${route.title} · 路线开场</h3>
      </div>
      <p class="sheet-copy">${segments[0].text} ${segments[1].text}</p>
      <div class="player">
        <div class="player-controls player-controls-row">
          <button class="primary-button" data-play-intro onclick="playRouteIntro()">${isActiveIntro ? icons.pause + "暂停开场" : icons.play + "播放开场"}</button>
          <button class="icon-button intro-skip" data-skip-intro onclick="skipIntroToFirstStop()">${icons.next}直接进入第 1 站</button>
        </div>
        <div class="progress-row">
          <span class="progress-elapsed">${formatClock(playbackElapsedSeconds())}</span>
          <div class="progress-track seekable" data-seek-bar onclick="seekBarEvent(event)" role="slider" aria-label="播放进度，点击跳转"><div class="progress-fill" style="width: ${state.progress}%"></div></div>
          <span>${currentPlaybackDurationLabel(route)}</span>
        </div>
        <div class="rate-row">
          <span class="rate-label">倍速</span>
          ${[0.75, 1, 1.25, 1.5]
            .map(
              (rate) => `
                <button class="rate-chip${state.playbackRate === rate ? " active" : ""}" data-rate="${rate}" onclick="setPlaybackRate(${rate})">${rate === 1 ? "1.0x" : `${rate}x`}</button>
              `
            )
            .join("")}
          <button class="music-toggle${state.musicOn ? " on" : ""}" data-music onclick="toggleMusic()">${state.musicOn ? "背景音 开" : "背景音 关"}</button>
        </div>
        <div class="audio-source-row">
          <span class="audio-source-pill${introAsset ? " asset" : ""}">${audioPlaybackSourceLabel(route, 0, "intro")}</span>
          <span>开场结束后从第 ${state.stopIndex + 1} 站正式开始。</span>
        </div>
        ${renderPlaybackStatus(route, getStop())}
      </div>
    </section>
  `;
}

function renderStopSheet(route, stop) {
  const next = nextStop(route);
  const source = currentAudioSourceInfo(route);
  const pauseCount = pauseSegmentsForStop(route, stop, state.stopIndex).length;
  const anchor = contentAnchorForStop(route, state.stopIndex);
  const sourceNote = sourceNoteForRoute(route);
  const photo = stopImageFor(route, state.stopIndex);
  return `
    <section class="stop-sheet" aria-live="polite">
      <div class="sheet-head">
        <div class="stop-index">第 ${state.stopIndex + 1} 站 / ${route.stops.length} · 本点语音 ${stopAudioDurationLabel(route, state.stopIndex)}</div>
        <h3>${stop.title}</h3>
      </div>
      ${photo ? `<figure class="stop-photo"><img src="${photo.src}" alt="${stop.title}实景" loading="lazy" onerror="this.closest('.stop-photo').remove()"><figcaption>${stop.title} · 影像资料${photo.credit ? `（${photo.credit}）` : ""}</figcaption></figure>` : ""}
      <dl class="sheet-facts">
        <div><dt>现在站位</dt><dd>${stop.location}</dd></div>
        <div><dt>朝向提示</dt><dd>${stop.cue}</dd></div>
        <div><dt>留白</dt><dd>${pauseCount} 段驻足/拍照空档</dd></div>
        <div><dt>下一点</dt><dd>${next ? next.title : "路线终点"}</dd></div>
      </dl>
      ${anchor ? `<div class="callout-anchor"><span>现场锚点</span><p>${anchor}</p>${sourceNote ? `<small>${sourceNote}</small>` : ""}</div>` : ""}
      <p class="sheet-copy">${stop.script}</p>
      <div class="player">
        <div class="player-controls">
          <button class="icon-button" data-prev onclick="goStop(-1)" aria-label="上一站">${icons.prev}</button>
          <button class="primary-button" data-play onclick="toggleAudio()">${playButtonLabel()}</button>
          <button class="icon-button" data-next onclick="goStop(1)" aria-label="下一站">${icons.next}</button>
        </div>
        <div class="progress-row">
          <span class="progress-elapsed">${formatClock(playbackElapsedSeconds())}</span>
          <div class="progress-track seekable" data-seek-bar onclick="seekBarEvent(event)" role="slider" aria-label="播放进度，点击跳转"><div class="progress-fill" style="width: ${state.progress}%"></div></div>
          <span>${currentPlaybackDurationLabel(route)}</span>
        </div>
        <div class="audio-source-row">
          <span class="audio-source-pill${source.hasAsset ? " asset" : ""}">${source.label}</span>
          <span>${source.detail}</span>
        </div>
        <div class="rate-row">
          <span class="rate-label">倍速</span>
          ${[0.75, 1, 1.25, 1.5]
            .map(
              (rate) => `
                <button class="rate-chip${state.playbackRate === rate ? " active" : ""}" data-rate="${rate}" onclick="setPlaybackRate(${rate})">${rate === 1 ? "1.0x" : `${rate}x`}</button>
              `
            )
            .join("")}
          <button class="music-toggle${state.musicOn ? " on" : ""}" data-music onclick="toggleMusic()">${state.musicOn ? "背景音 开" : "背景音 关"}</button>
        </div>
        ${renderPlaybackStatus(route, stop)}
      </div>
      <div class="sheet-actions">
        <button class="transcript-toggle" data-tab="${state.tab === "script" ? "info" : "script"}" onclick="setTab('${state.tab === "script" ? "info" : "script"}')">
          ${state.tab === "script" ? "收起文字稿" : "查看文字稿"}
        </button>
        <span class="sheet-next"><strong>听完走法：</strong>${stop.next}</span>
      </div>
      ${
        state.tab === "script"
          ? `<div class="script-block">${renderLongTranscript(route, stop, state.stopIndex)}<div class="next-step"><strong>下一步：</strong>${stop.next}</div></div>`
          : ""
      }
      <button class="sheet-next-action" data-next onclick="goStop(1)" ${next ? "" : "disabled"}>${next ? icons.next + "到达下一站：" + next.title : "路线完成"}</button>
    </section>
  `;
}

function renderRouteCompletion(route) {
  return `
    <div class="route-complete" aria-live="polite">
      <div>
        <span>路线听完</span>
        <strong>${route.title}</strong>
        <p>已覆盖 ${route.stops.length} 个点位，语音约 ${audioDurationLabel(route)}。可以重听整线，也可以导出完整脚本做后续审稿。</p>
      </div>
      <div class="route-complete-actions">
        <button class="route-tour-button active" data-route-tour onclick="toggleRouteTour()">${icons.play}重听整线</button>
        <button class="download-toggle" data-download onclick="toggleDownload()">${icons.download}导出脚本</button>
      </div>
    </div>
  `;
}

function renderRouteGuide(route, stop) {
  const next = nextStop(route);
  const progress = routeProgressPercent(route);
  const movement = next ? stop.next : "路线已经到终点。停在这里回看刚才走过的方向，整理照片和听感。";
  const nextLabel = next ? `第 ${state.stopIndex + 2} 站 · ${next.title}` : "已到终点";
  const tourStatus = state.routeTourMode
    ? state.playbackMode === "intro"
      ? `整线开场中：开场结束后进入「${stop.title}」。`
      : `整线播放中：本点结束后自动进入${next ? `「${next.title}」` : "路线收束"}。`
    : state.routeTourCompleted
      ? "整条路线已听完，可以从第 1 站重听或进入下一条景点。"
      : next
        ? `可从第 ${state.stopIndex + 1} 站开始连续听完剩余路线。`
        : "当前已在终点，可播放本点收束；如要完整路线，请回到第 1 站。";
  const tourButtonLabel = state.routeTourMode
    ? `${icons.pause}停止整线`
    : `${icons.play}${state.routeTourCompleted ? "重听整线" : next ? "开始整线" : "播放终点"}`;
  return `
    <div class="route-guide" aria-live="polite">
      <div class="route-guide-status">
        <span class="route-guide-kicker">现场导览</span>
        <strong>第 ${state.stopIndex + 1} 站 · ${stop.title}</strong>
        <span>下一步：${nextLabel}</span>
        <span>${tourStatus}</span>
      </div>
      <div class="route-guide-motion">
        <span>行走指令</span>
        <p>${movement}</p>
      </div>
      <div class="route-guide-progress" aria-label="路线进度 ${progress}%">
        <div class="route-guide-track"><div class="route-guide-fill" style="width: ${progress}%"></div></div>
        <span>${state.stopIndex + 1}/${route.stops.length}</span>
      </div>
      <div class="route-guide-actions">
        <button class="route-tour-button${state.routeTourMode ? " active" : ""}" data-route-tour onclick="toggleRouteTour()">${tourButtonLabel}</button>
      </div>
    </div>
  `;
}

function playRouteIntro() {
  if (state.isPlaying && state.playbackMode === "intro") {
    state.pausedSeconds = playbackElapsedSeconds();
    stopAudio();
    return;
  }
  speakRouteIntro();
}

function skipIntroToFirstStop() {
  selectStopAndPlay(0);
}

function playCityIntro() {
  if (state.isPlaying) {
    stopAudio();
    return;
  }
  const city = getCity();
  const text = cityIntros[city.id] || city.overview;
  const durationSeconds = Math.round(estimateSpeechSeconds(text)) + 4;
  const asset = {
    src: `audio-assets/cities/${city.id}.mp3`,
    durationSeconds,
    label: `${city.name} · 城市开场`
  };
  const fallback = () => {
    stopAudio(false);
    state.isPlaying = true;
    state.playbackMode = "intro";
    state.audioSourceMode = "speech";
    state.playStartedAt = Date.now();
    state.playDurationSeconds = durationSeconds;
    speakText(text);
    render();
  };
  playAudioAsset(asset, {
    mode: "intro",
    route: getRoute(),
    stopIndex: 0,
    durationSeconds,
    fallback
  });
}

function render() {
  const city = getCity();
  const route = getRoute();
  const stop = getStop();

  if (state.view === "cities") {
    app.innerHTML = renderHomeView();
    return;
  }
  if (state.view === "routes") {
    app.innerHTML = renderCityView(city);
    return;
  }
  app.innerHTML = renderRouteView(city, route, stop);
}

function handleAction(target) {
  const action = target.closest(
    "[data-city], [data-route], [data-stop], [data-view], [data-intro], [data-tab], [data-rate], [data-music], [data-seek], [data-skip-intro], [data-play-city-intro], [data-download], [data-library-download], [data-play], [data-play-intro], [data-prev], [data-next], [data-route-tour], [data-review-check]"
  );
  if (!action || !app.contains(action)) return false;

  if (action.dataset.city) setCity(action.dataset.city);
  else if (action.dataset.route) setRoute(action.dataset.route);
  else if (action.dataset.view === "cities") showCities();
  else if (action.dataset.view === "routes") showCityRoutes();
  else if (action.dataset.intro !== undefined) selectIntroAndPlay();
  else if (action.dataset.stop) selectStopAndPlay(Number(action.dataset.stop));
  else if (action.dataset.tab) setTab(action.dataset.tab);
  else if (action.dataset.rate) setPlaybackRate(action.dataset.rate);
  else if (action.dataset.music !== undefined) toggleMusic();
  else if (action.dataset.seek) seekPlayback(Number(action.dataset.seek));
  else if (action.dataset.download !== undefined) toggleDownload();
  else if (action.dataset.libraryDownload !== undefined) toggleLibraryDownload();
  else if (action.dataset.play !== undefined) toggleAudio();
  else if (action.dataset.playIntro !== undefined) playRouteIntro();
  else if (action.dataset.skipIntro !== undefined) skipIntroToFirstStop();
  else if (action.dataset.playCityIntro !== undefined) playCityIntro();
  else if (action.dataset.prev !== undefined) goStop(-1);
  else if (action.dataset.next !== undefined) goStop(1);
  else if (action.dataset.routeTour !== undefined) toggleRouteTour();
  else if (action.dataset.reviewCheck) toggleReviewCheck(action.dataset.reviewCheck);
  return true;
}

app.addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  if (event.target.closest("button")) return;
  if (handleAction(event.target)) event.preventDefault();
});

window.addEventListener("beforeunload", () => {
  window.speechSynthesis?.cancel();
});

applyInitialUrlState();
render();
loadAudioAssetManifest();
